package com.bossorbs;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import net.runelite.client.util.Text;

/**
 * Works out which hiscores boss an NPC is, so its orb can carry that boss's icon.
 *
 * <p>The boss list itself comes from RuneLite's hiscores, so a boss added to the
 * hiscores is picked up without a change here as long as the NPC carries the
 * same name. Only the ones whose NPC is named differently from their hiscores
 * entry - the Gauntlet's Hunllef, Dusk and Dawn - are listed by hand.
 *
 * <p>Raids, Barrows and the Moons of Peril are left out on purpose. The hiscores
 * count a whole raid, or a chest at the end of a run of bosses, as one entry.
 * Every boss on the way would wear the same icon, and the count would not be
 * that boss's own.
 */
@Slf4j
@Singleton
class BossCatalogue
{
	/**
	 * NPC name, then the hiscores entry it counts towards.
	 */
	private static final String[][] ALIASES = {
		{"Crystalline Hunllef", "The Gauntlet"},
		{"Corrupted Hunllef", "The Corrupted Gauntlet"},

		{"Dusk", "Grotesque Guardians"},
		{"Dawn", "Grotesque Guardians"},

		{"Branda the Fire Queen", "The Royal Titans"},
		{"Eldric the Ice King", "The Royal Titans"},
	};

	private final Map<String, HiscoreSkill> byName = new HashMap<>();

	/** Hiscores entries by their own names only, without the NPC names that count towards them. */
	private final Map<String, HiscoreSkill> hiscores = new HashMap<>();

	@Inject
	BossCatalogue()
	{
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill.getType() == HiscoreSkillType.BOSS)
			{
				byName.put(key(skill.getName()), skill);
				hiscores.put(key(skill.getName()), skill);
			}
		}

		for (String[] alias : ALIASES)
		{
			HiscoreSkill skill = byName.get(key(alias[1]));
			if (skill == null)
			{
				// A renamed hiscores entry shouldn't break the plugin, just that icon.
				log.debug("No hiscores entry called '{}' for {}", alias[1], alias[0]);
				continue;
			}

			byName.putIfAbsent(key(alias[0]), skill);
		}
	}

	/**
	 * The hiscores boss an NPC name belongs to, or null if it isn't one.
	 */
	HiscoreSkill match(String npcName)
	{
		if (npcName == null)
		{
			return null;
		}

		String key = key(Text.removeTags(npcName));
		if (key.isEmpty())
		{
			return null;
		}

		HiscoreSkill skill = byName.get(key);
		if (skill != null)
		{
			return skill;
		}

		// "The Nightmare" is "Nightmare" on the hiscores, and "Hueycoatl" the reverse.
		return key.startsWith("the") ? byName.get(key.substring(3)) : byName.get("the" + key);
	}

	/**
	 * The hiscores entry with exactly this name, or null if there isn't one.
	 */
	HiscoreSkill hiscore(String name)
	{
		return hiscores.get(key(name));
	}

	/**
	 * Lower case with punctuation and spaces dropped, so "Kree'arra" and
	 * "Kree'Arra" - or "TzTok-Jad" and "Tztok-jad" - come out the same.
	 */
	static String key(String name)
	{
		StringBuilder builder = new StringBuilder(name.length());
		for (int i = 0; i < name.length(); i++)
		{
			char c = Character.toLowerCase(name.charAt(i));
			if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))
			{
				builder.append(c);
			}
		}

		return builder.toString();
	}
}

package com.bossorbs;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(BossOrbsConfig.GROUP)
public interface BossOrbsConfig extends Config
{
	String GROUP = "bossorbs";

	@ConfigSection(
		name = "Orbs",
		description = "When the orbs show, what they look like and how they are laid out",
		position = 0
	)
	String orbSection = "orbSection";

	@ConfigSection(
		name = "Behaviour",
		description = "What the orbs do around a fight, and what clicking one does",
		position = 1
	)
	String behaviourSection = "behaviourSection";

	@ConfigSection(
		name = "Text",
		description = "The health number and everything else written on and under each orb",
		position = 2
	)
	String textSection = "textSection";

	@ConfigSection(
		name = "Colours",
		description = "Colours as the boss loses health",
		position = 3,
		closedByDefault = true
	)
	String colourSection = "colourSection";

	@ConfigItem(
		keyName = "showWhen",
		name = "Show orbs",
		description = "Show an orb as soon as a boss is nearby, or only once it has taken damage or you have"
			+ " attacked it. Every boss nearby gets its own orb",
		section = orbSection,
		position = 0
	)
	default ShowWhen showWhen()
	{
		return ShowWhen.NEARBY;
	}

	@ConfigItem(
		keyName = "orbDesign",
		name = "Design",
		description = "The look of the orbs",
		section = orbSection,
		position = 1
	)
	default OrbDesign design()
	{
		return OrbDesign.GLASS;
	}

	@ConfigItem(
		keyName = "layout",
		name = "Layout",
		description = "Put several bosses side by side or stack them",
		section = orbSection,
		position = 2
	)
	default OrbLayout layout()
	{
		return OrbLayout.VERTICAL;
	}

	@Range(min = 32, max = 128)
	@ConfigItem(
		keyName = "orbSize",
		name = "Orb size",
		description = "Diameter of each orb in pixels",
		section = orbSection,
		position = 3
	)
	default int orbSize()
	{
		return 45;
	}

	@Range(max = 40)
	@ConfigItem(
		keyName = "spacing",
		name = "Spacing",
		description = "Space between orbs in pixels",
		section = orbSection,
		position = 4
	)
	default int spacing()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "compact",
		name = "Compact",
		description = "Draw the orbs at the compact size and without their text, so they take up less of the"
			+ " screen. Everything is still there when you hover over an orb",
		section = orbSection,
		position = 5
	)
	default boolean compact()
	{
		return false;
	}

	@Range(min = 16, max = 128)
	@ConfigItem(
		keyName = "compactSize",
		name = "Compact orb size",
		description = "Diameter of each orb in pixels when Compact is on",
		section = orbSection,
		position = 6
	)
	default int compactSize()
	{
		return 45;
	}

	@ConfigItem(
		keyName = "openWiki",
		name = "Open the wiki",
		description = "Open the boss's OSRS Wiki page from its orb. Right-clicking offers its strategy guide too."
			+ " Left-click keeps the right-click options, and stops that click from reaching the game behind"
			+ " the orb",
		section = behaviourSection,
		position = 2
	)
	default WikiLink wikiLink()
	{
		return WikiLink.MENU;
	}

	@ConfigItem(
		keyName = "respawnTimer",
		name = "Respawn countdown",
		description = "When a boss that respawns on a timer dies, keep its orb and refill it as the respawn"
			+ " approaches",
		section = behaviourSection,
		position = 0
	)
	default boolean respawnTimer()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightTarget",
		name = "Highlight your target",
		description = "With more than one orb showing, ring the boss you are attacking",
		section = behaviourSection,
		position = 1
	)
	default boolean highlightTarget()
	{
		return true;
	}

	@ConfigItem(
		keyName = "replaceBar",
		name = "Replace HP bar with orb",
		description = "Draw each boss's orb over the boss in place of its health bar, and hide the game's own bars:"
			+ " the wide one at the top of the screen and the one over the boss. An orb over a boss can't be"
			+ " left-clicked, so clicks still reach the boss",
		section = behaviourSection,
		position = 3
	)
	default boolean replaceBar()
	{
		return false;
	}

	@ConfigItem(
		keyName = "healthText",
		name = "Health",
		description = "What to show under the orb. Falls back to a percentage for a boss whose maximum isn't known",
		section = textSection,
		position = 0
	)
	default HealthText healthText()
	{
		return HealthText.HITPOINTS;
	}

	@ConfigItem(
		keyName = "numberFont",
		name = "Health size",
		description = "Font used for the health number",
		section = textSection,
		position = 1
	)
	default NumberFont numberFont()
	{
		return NumberFont.SMALL;
	}

	@ConfigItem(
		keyName = "scaleText",
		name = "Scale text with the orb",
		description = "Make the numbers and names bigger with a bigger orb. They stay at their normal size for a"
			+ " smaller one, where the game's fonts would become hard to read",
		section = textSection,
		position = 2
	)
	default boolean scaleText()
	{
		return true;
	}

	@ConfigItem(
		keyName = "healthColoured",
		name = "Colour by health",
		description = "Colour the health number green, yellow, orange and red as the boss gets low, using the"
			+ " colours and thresholds under Colours",
		section = textSection,
		position = 3
	)
	default boolean healthColoured()
	{
		return true;
	}

	@ConfigItem(
		keyName = "healthPlate",
		name = "Number plate",
		description = "Put the health number on a small dark plate edged in the health colour",
		section = textSection,
		position = 4
	)
	default boolean healthPlate()
	{
		return false;
	}

	@ConfigItem(
		keyName = "healthAttached",
		name = "Attach health to orb",
		description = "Sit the health number on the bottom edge of the orb, rather than below it",
		section = textSection,
		position = 5
	)
	default boolean healthAttached()
	{
		return true;
	}

	@ConfigItem(
		keyName = "damageNumbers",
		name = "Damage numbers",
		description = "Show each hit and heal beside the health number as it happens, where the game gives the"
			+ " boss's exact hitpoints",
		section = textSection,
		position = 6
	)
	default boolean damageNumbers()
	{
		return false;
	}

	@ConfigItem(
		keyName = "killTimer",
		name = "Kill timer",
		description = "Show how long the fight has been going under the orb. Your best time is shown when you"
			+ " hover over the orb",
		section = textSection,
		position = 7
	)
	default boolean killTimer()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showName",
		name = "Boss name",
		description = "Show the boss's name under its orb",
		section = textSection,
		position = 8
	)
	default boolean showName()
	{
		return false;
	}

	@ConfigItem(
		keyName = "killCount",
		name = "Kill count",
		description = "Show your kill count for the boss, read from your hiscores when you log in and kept up to"
			+ " date from the kill count messages in chat",
		section = textSection,
		position = 9
	)
	default KillCountPlace killCount()
	{
		return KillCountPlace.ORB;
	}

	@ConfigItem(
		keyName = "killCountPlate",
		name = "Kill count plate",
		description = "Put the kill count on a small dark plate edged in the kill count colour",
		section = textSection,
		position = 10
	)
	default boolean killCountPlate()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		keyName = "textColour",
		name = "Text colour",
		description = "Colour of the boss name, and of the health number when it isn't coloured by health",
		section = textSection,
		position = 11
	)
	default Color textColour()
	{
		return Color.WHITE;
	}

	@Alpha
	@ConfigItem(
		keyName = "killCountColour",
		name = "Kill count colour",
		description = "Colour of the kill count",
		section = textSection,
		position = 12
	)
	default Color killCountColour()
	{
		return new Color(250, 255, 0);
	}

	@Alpha
	@ConfigItem(
		keyName = "outlineColour",
		name = "Outline colour",
		description = "Colour of the outline behind any text that isn't on a plate",
		section = textSection,
		position = 13
	)
	default Color outlineColour()
	{
		return new Color(0, 0, 0, 235);
	}

	@Range(min = 1, max = 3)
	@ConfigItem(
		keyName = "outlineWidth",
		name = "Outline thickness",
		description = "How thick the outline behind the text is, in pixels",
		section = textSection,
		position = 14
	)
	default int outlineWidth()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "palette",
		name = "Palette",
		description = "Standard uses the four health colours below. Colour-blind safe swaps them, and the colours"
			+ " of hits, heals and respawns, for a set that stays distinct with red-green colour blindness",
		section = colourSection,
		position = 0
	)
	default ColourPalette palette()
	{
		return ColourPalette.STANDARD;
	}

	@Alpha
	@ConfigItem(
		keyName = "highColour",
		name = "High health",
		description = "Colour at or above the high threshold",
		section = colourSection,
		position = 1
	)
	default Color highColour()
	{
		return new Color(46, 196, 78);
	}

	@Alpha
	@ConfigItem(
		keyName = "midColour",
		name = "Mid health",
		description = "Colour at or above the mid threshold",
		section = colourSection,
		position = 2
	)
	default Color midColour()
	{
		return new Color(236, 212, 44);
	}

	@Alpha
	@ConfigItem(
		keyName = "lowColour",
		name = "Low health",
		description = "Colour at or above the low threshold",
		section = colourSection,
		position = 3
	)
	default Color lowColour()
	{
		return new Color(240, 140, 34);
	}

	@Alpha
	@ConfigItem(
		keyName = "criticalColour",
		name = "Critical health",
		description = "Colour below the low threshold",
		section = colourSection,
		position = 4
	)
	default Color criticalColour()
	{
		return new Color(220, 44, 44);
	}

	@Range(max = 100)
	@ConfigItem(
		keyName = "highThreshold",
		name = "High threshold",
		description = "Health percentage at or above which the high colour is used",
		section = colourSection,
		position = 5
	)
	default int highThreshold()
	{
		return 75;
	}

	@Range(max = 100)
	@ConfigItem(
		keyName = "midThreshold",
		name = "Mid threshold",
		description = "Health percentage at or above which the mid colour is used",
		section = colourSection,
		position = 6
	)
	default int midThreshold()
	{
		return 50;
	}

	@Range(max = 100)
	@ConfigItem(
		keyName = "lowThreshold",
		name = "Low threshold",
		description = "Health percentage at or above which the low colour is used",
		section = colourSection,
		position = 7
	)
	default int lowThreshold()
	{
		return 25;
	}

	@Alpha
	@ConfigItem(
		keyName = "backgroundColour",
		name = "Orb background",
		description = "Colour of the orb behind the icon",
		section = colourSection,
		position = 8
	)
	default Color backgroundColour()
	{
		return new Color(16, 16, 20, 225);
	}
}

package com.bossorbs;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.AffineTransform;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Rectangle2D;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
