import net.runelite.client.util.QuantityFormatter;

/**
 * One orb per boss: its hiscores icon in the middle, health shown around or
 * behind it depending on the chosen design, and the number below.
 */
@Singleton
public class BossOrbsOverlay extends Overlay
{
	private static final Color PLATE_FILL = new Color(12, 12, 16, 215);
	private static final Color BADGE_FILL = new Color(12, 12, 16, 235);
	/**
	 * Where copies of a piece of text are drawn to build up an outline behind it,
	 * for each thickness of outline: every whole-pixel step that lies within that
	 * distance, which leaves no gaps however thick it gets.
	 */
	private static final int THICKEST_OUTLINE = 4;
	private static final int[][][] OUTLINE_STEPS = outlineSteps();

	/** Room left around each orb for its shadow. */
	private static final int PAD = 4;

	private static final int TEXT_GAP = 3;
	private static final int PLATE_PAD_X = 6;
	private static final int PLATE_PAD_Y = 3;
	private static final int BADGE_PAD_X = 4;
	private static final int BADGE_PAD_Y = 3;

	/** The RuneScape fonts leave a pixel after every character, the last one included. */
	private static final int TRAILING_SPACE = 1;

	/** How much of the health number's height overlaps the orb when it is attached to it. */
	private static final float HEALTH_OVERLAP = 0.4f;

	/** cos 45 degrees: how far along each axis the badge sits from the orb's centre, in radii. */
	private static final double BADGE_OFFSET = 0.7071;

	/** How much of the space inside an orb the icon may take up. */
	private static final float ICON_SHARE = 0.78f;

	/** Names are cut short past this much wider than the orb, so one long name can't spread the row out. */
	private static final int NAME_OVERHANG = 48;

	/**
	 * Roughly how long the orb takes to glide to a new reading, how long the pale
	 * trail of the health just lost stays put, and how long it then takes to follow.
	 */
	private static final double GLIDE_MS = 300;
	private static final double TRAIL_GLIDE_MS = 420;
	private static final int TRAIL_HOLD_MS = 450;

	/** How quickly an orb's colour follows it from one health band into the next. */
	private static final double COLOUR_EASE_MS = 170;

	/** How long an orb takes to fade in when its boss turns up. */
	private static final int APPEAR_MS = 240;

	/** The orb size the text is at its natural size for, and how far it grows with a bigger orb. */
	private static final int NATURAL_ORB = 58;
	private static final float MAX_TEXT_SCALE = 2.2f;

	/** Readings closer together than this are the same reading. */
	private static final double SETTLED = 0.002;

	private static final int HIT_MS = 320;
	private static final int HEAL_MS = 750;
	private static final int KILL_POP_MS = 520;

	/** How long the "+1" beside the kill count lasts, and how far it drifts up as it fades. */
	private static final int GAIN_MS = 1700;
	private static final int GAIN_RISE = 12;
	private static final int FADE_MS = 500;

	private static final Color HEAL_GLOW = new Color(120, 255, 150);
	private static final Color GAIN = new Color(126, 255, 142);

	/** How long a hit or heal stays written beside the health number, and how far it drifts up. */
	private static final int CHANGE_MS = 1000;
	private static final int CHANGE_RISE = 9;
	private static final Color DAMAGE = new Color(255, 122, 110);

	/** One beat of the pulse an orb takes on at critical health. */
	private static final int PULSE_MS = 900;

	/** An orb counting down to a respawn, and the icon of the boss it is waiting on. */
	private static final Color RESPAWN = new Color(112, 172, 255);
	private static final float WAITING_ICON = 0.45f;

	private static final Color TARGET_RING = new Color(255, 240, 170, 240);

	/**
	 * The colour-blind safe palette: blues for healthy, yellow and orange for low,
	 * which stay apart from one another with red-green colour blindness. Hits and
	 * heals follow suit, and a respawning orb turns grey so it isn't taken for a
	 * healthy one.
	 */
	private static final Color SAFE_HIGH = new Color(48, 128, 236);
	private static final Color SAFE_MID = new Color(124, 204, 242);
	private static final Color SAFE_LOW = new Color(240, 228, 66);
	private static final Color SAFE_CRITICAL = new Color(224, 96, 20);
	private static final Color SAFE_GAIN = new Color(150, 214, 255);
	private static final Color SAFE_DAMAGE = new Color(255, 170, 70);
	private static final Color SAFE_RESPAWN = new Color(184, 190, 204);

	/**
	 * How far above a boss's head its orb is anchored when it stands in for the
	 * health bar, which is about where the game draws that bar.
	 */
	private static final int HEAD_ROOM = 20;

	/** The corner of the canvas, which is where an overlay over the whole game view draws from. */
	private static final Rectangle CANVAS_ORIGIN = new Rectangle();

	/** Where an orb that isn't on screen this frame is put on record, so the mouse can't find it. */
	private static final int OFF_SCREEN = -100_000;

	/** Scaled icons are kept, but not without limit while the orb size is being dragged about. */
	private static final int ICON_CACHE_LIMIT = 128;

	/** How many of the icons in use are kept where they can be found without a map lookup. */
	private static final int ICONS_TO_HAND = 8;

	/** Line widths come in tenths of a pixel, and each width's stroke is made only once. */
	private static final BasicStroke[] STROKES = new BasicStroke[64];

	private final Client client;
	private final BossOrbsPlugin plugin;
	private final BossOrbsConfig config;
	private final SpriteManager spriteManager;
	private final TooltipManager tooltipManager;

	/** Boss icons as the game has them, and scaled to size with a dark outline so they read against any fill. */
	private final Map<Integer, BufferedImage> sprites = new HashMap<>();
	private final Map<Integer, BufferedImage> icons = new HashMap<>();

	private final OrbArt art = new OrbArt();

	// The overlay is drawn every frame, so what it needs each time is kept and
	// reused rather than made again: the lists of what is under each orb, the
	// shapes of the plates, and colours worked out from the settings.

	private int[] killCounts = new int[0];
	private long[] respawns = new long[0];
	private int[] orbXs = new int[0];
	private int[] orbYs = new int[0];
	private String[] healthTexts = new String[0];
	private String[] timers = new String[0];
	private String[] names = new String[0];
	private String[] killCountTexts = new String[0];

	private final RoundRectangle2D.Float pill = new RoundRectangle2D.Float();

	private final int[] iconKeys = new int[ICONS_TO_HAND];
	private final BufferedImage[] iconsToHand = new BufferedImage[ICONS_TO_HAND];
	private int nextIcon;

	/** The kill count colour the badge edges were made from, and the edges at rest and during a kill. */
	private Color badgeColour;
	private Color badgeEdge;
	private Color badgeEdgeLit;

	/** The text colour the kill timer's dimmer shade was made from, and that shade. */
	private Color timerFrom;
	private Color timerColour;

	/** When the last frame was drawn, in nanoseconds, for pacing the animations. */
	private long lastFrame;

	/** The speed the last glide ended at, handed back alongside where it got to. */
	private double glideSpeed;

	/**
	 * How much bigger than natural the text is this frame, and the measurements
	 * that grow with it. The game's fonts go ragged below their natural size, so
	 * the text grows with a big orb but never shrinks with a small one.
	 */
	private float textScale = 1;
	private int platePadX = PLATE_PAD_X;
	private int platePadY = PLATE_PAD_Y;
	private int badgePadX = BADGE_PAD_X;
	private int badgePadY = BADGE_PAD_Y;
	private int textGap = TEXT_GAP;
	private int trailingSpace = TRAILING_SPACE;
	private int gainRise = GAIN_RISE;
	private int changeRise = CHANGE_RISE;
	private int nameOverhang = NAME_OVERHANG;

	/** How thick the outline behind the text is this frame, the steps that draw it, and its colour. */
	private int outline = 1;
	private int[][] outlineSteps = OUTLINE_STEPS[1];
	private Color outlineColour = Color.BLACK;

	/** Whether the colour-blind safe palette is in use this frame. */
	private boolean safeColours;

	/** The fonts at the current text scale, by the font they were enlarged from. */
	private final Map<Font, Font> scaledFonts = new HashMap<>();

	/** Where each orb was drawn last frame, read by the mouse listener from another thread. */
	private volatile List<WikiTarget> wikiTargets = Collections.emptyList();

	/**
	 * Whether a left click on one of those orbs is the overlay's to take. It isn't
	 * while the orbs are over the bosses, where a click has to reach the boss.
	 */
	private volatile boolean orbsClickable = true;

	/**
	 * Opens the wiki on a left click, when that is switched on. The click is kept
	 * from the game, so it can't also land on whatever is behind the orb.
	 */
	final MouseAdapter wikiClicks = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			if (!orbsClickable || config.wikiLink() != WikiLink.CLICK || event.getButton() != MouseEvent.BUTTON1
				|| event.isAltDown() || event.isConsumed())
			{
				return event;
			}

			WikiTarget target = targetAt(event.getX(), event.getY());
			if (target != null)
			{
				event.consume();
				LinkBrowser.browse(target.url());
			}

			return event;
		}
	};

	/** Top and bottom of each font's digits above its baseline, measured on first use. */
	private final Map<Font, int[]> digitExtents = new HashMap<>();

	@Inject
	private BossOrbsOverlay(Client client, BossOrbsPlugin plugin, BossOrbsConfig config,
		SpriteManager spriteManager, TooltipManager tooltipManager)
	{
		this.tooltipManager = tooltipManager;
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.spriteManager = spriteManager;

		setPosition(OverlayPosition.TOP_CENTER);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<TrackedBoss> bosses = plugin.visibleBosses();
		if (bosses.isEmpty())
		{
			setWikiTargets(Collections.emptyList());
			return null;
		}

		if (config.replaceBar())
		{
			// With the orbs standing in for the health bars, the bosses are drawn
			// over their own heads by the overlay that covers the game view.
			return null;
		}

		safeColours = config.palette() == ColourPalette.COLOUR_BLIND;

		Object previousAliasing = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		Object previousInterpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);

		Dimension drawn = renderBosses(graphics, bosses, false);

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
			previousAliasing == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : previousAliasing);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			previousInterpolation == null ? RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR : previousInterpolation);
		return drawn;
	}

	/**
	 * Draws each boss's orb over its own head rather than in a row. The overlay
	 * that covers the game view calls this, with graphics that start at the
	 * corner of the canvas.
	 */
	void renderOverHeads(Graphics2D graphics, List<TrackedBoss> bosses)
	{
		safeColours = config.palette() == ColourPalette.COLOUR_BLIND;

		Object previousAliasing = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		Object previousInterpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);

		renderBosses(graphics, bosses, true);

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
			previousAliasing == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : previousAliasing);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			previousInterpolation == null ? RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR : previousInterpolation);
	}

	/**
	 * Finds the point on the canvas just above a boss's head, where its health bar
	 * would be. A boss that has died and gone keeps the spot it was last seen at.
	 *
	 * @return whether that point is on screen
	 */
	private boolean findHead(TrackedBoss boss)
	{
		NPC npc = boss.npc;
		if (boss.goneAt == 0)
		{
			LocalPoint point = npc.getLocalLocation();
			if (point != null)
			{
				boss.lastPoint = point;
				boss.lastHeight = npc.getLogicalHeight();
			}
		}

		if (boss.lastPoint == null)
		{
			return false;
		}

		Point head = Perspective.localToCanvas(client, boss.lastPoint, client.getTopLevelWorldView().getPlane(),
			boss.lastHeight + HEAD_ROOM);
		if (head == null)
		{
			return false;
		}

		boss.headX = head.getX();
		boss.headY = head.getY();
		return true;
	}

	private void setWikiTargets(List<WikiTarget> targets)
	{
		wikiTargets = targets;
	}

	/**
	 * The orb at a point on the canvas, if there is one and wiki links are on.
	 */
	WikiTarget targetAt(int x, int y)
	{
		for (WikiTarget target : wikiTargets)
		{
			if (target.bounds.contains(x, y))
			{
				return target;
			}
		}

		return null;
	}

	/**
	 * Sets how big the text is drawn, and everything that is measured from it.
	 */
	private void setTextScale(float scale)
	{
		// The outline grows with the text, so the two keep their proportions.
		outlineColour = config.outlineColour();
		int thickness = Math.max(1, Math.min(THICKEST_OUTLINE, config.outlineWidth() * Math.max(1, Math.round(scale))));
		if (scale == textScale && thickness == outline)
		{
			return;
		}

		scaledFonts.clear();
		textScale = scale;
		outline = thickness;
		outlineSteps = OUTLINE_STEPS[thickness];
		platePadX = Math.round(PLATE_PAD_X * scale);
		platePadY = Math.round(PLATE_PAD_Y * scale);
		badgePadX = Math.round(BADGE_PAD_X * scale);
		badgePadY = Math.round(BADGE_PAD_Y * scale);
		textGap = Math.round(TEXT_GAP * scale) + (thickness - Math.max(1, Math.round(scale))) * 2;
		trailingSpace = Math.round(TRAILING_SPACE * scale);
		gainRise = Math.round(GAIN_RISE * scale);
		changeRise = Math.round(CHANGE_RISE * scale);
		nameOverhang = Math.round(NAME_OVERHANG * scale);
	}

	private static int[][][] outlineSteps()
	{
		int[][][] steps = new int[THICKEST_OUTLINE + 1][][];
		for (int thickness = 0; thickness <= THICKEST_OUTLINE; thickness++)
		{
			// A little over the thickness squared takes in the diagonals, which is
			// what makes one pixel of outline the usual eight steps.
			int reach = thickness * thickness + thickness;
			List<int[]> within = new ArrayList<>();
			for (int y = -thickness; y <= thickness; y++)
			{
				for (int x = -thickness; x <= thickness; x++)
				{
					if ((x != 0 || y != 0) && x * x + y * y <= reach)
					{
						within.add(new int[]{x, y});
					}
				}
			}

			steps[thickness] = within.toArray(new int[0][]);
		}

		return steps;
	}

	private Font scaled(Font font)
	{
		if (textScale == 1)
		{
			return font;
		}

		// Whole point sizes, which the game's fonts hold their shape at best.
		return scaledFonts.computeIfAbsent(font,
			natural -> natural.deriveFont((float) Math.round(natural.getSize2D() * textScale)));
	}

	private Dimension renderBosses(Graphics2D graphics, List<TrackedBoss> bosses, boolean overHeads)
	{
		int spacing = config.spacing();
		boolean horizontal = config.layout() == OrbLayout.HORIZONTAL;
		OrbDesign design = config.design();
		int count = bosses.size();

		// Compact orbs are a size of their own and shed their text, which is still
		// to be had by hovering over one.
		boolean compact = config.compact();
		int size = compact ? config.compactSize() : config.orbSize();

		setTextScale(config.scaleText()
			? Math.max(1f, Math.min(MAX_TEXT_SCALE, size / (float) NATURAL_ORB)) : 1f);
		Font numberFont = scaled(config.numberFont().font());
		Font nameFont = scaled(FontManager.getRunescapeSmallFont());
		FontMetrics numberMetrics = graphics.getFontMetrics(numberFont);
		FontMetrics nameMetrics = graphics.getFontMetrics(nameFont);

		// Paced off the fine-grained clock, so the easing is even from frame to frame.
		long now = System.currentTimeMillis();
		long frame = System.nanoTime();
		double elapsed = Math.max(0, Math.min(100, (frame - lastFrame) / 1_000_000.0));
		lastFrame = frame;
		for (TrackedBoss boss : bosses)
		{
			animate(boss, now, elapsed);
		}

		boolean showHealth = !compact && config.healthText() != HealthText.NONE;
		boolean showName = !compact && config.showName();
		boolean showTimer = !compact && config.killTimer();
		boolean plate = config.healthPlate();
		KillCountPlace killCountPlace = compact ? KillCountPlace.OFF : config.killCount();
		boolean killCountPlate = config.killCountPlate();
		int[] digits = digitExtent(graphics, numberFont);
		int lineHeight = nameMetrics.getAscent() + textGap;

		// What is written under each orb, worked out first because the widest of it
		// sets the width of every cell, which keeps the orbs evenly spaced.
		int orbBox = size + PAD * 2;
		int cellWidth = orbBox;
		reserve(count);
		boolean killCountRow = false;
		for (int i = 0; i < count; i++)
		{
			TrackedBoss boss = bosses.get(i);
			healthTexts[i] = null;
			timers[i] = null;
			names[i] = null;
			int killCount = plugin.killCount(boss);
			killCounts[i] = killCount;
			killCountTexts[i] = killCount < 0 || killCountPlace == KillCountPlace.OFF
				? null : killCountText(boss, killCount, killCountPlace == KillCountPlace.BELOW);
			killCountRow |= killCount >= 0 && killCountPlace == KillCountPlace.BELOW;

			// A boss that is on its way back shows how long is left in place of its health.
			respawns[i] = respawnLeft(boss, now);
			if (showHealth)
			{
				healthTexts[i] = respawns[i] >= 0 ? respawnText(boss, (respawns[i] + 999) / 1000) : healthText(boss);
				cellWidth = Math.max(cellWidth,
					numberMetrics.stringWidth(healthTexts[i]) + (plate ? platePadX * 2 + 2 : 2));
			}

			if (showTimer && boss.fightStart != 0)
			{
				timers[i] = timerText(boss, ((boss.fightEnd != 0 ? boss.fightEnd : now) - boss.fightStart) / 1000);
			}

			if (showName)
			{
				names[i] = fittedName(boss, nameFont, nameMetrics, size + nameOverhang);
				cellWidth = Math.max(cellWidth, nameMetrics.stringWidth(names[i]) + 2);
			}
		}

		// The health number either hangs below the orb or sits on its bottom edge,
		// overlapping it a little the way the kill count overlaps its corner. Sat on
		// the edge, only the part that sticks out below the orb takes up room.
		int healthSize = digits[0] - digits[1] + (plate ? platePadY * 2 : 2);
		int healthHeight = !showHealth ? 0
			: config.healthAttached() ? Math.max(0, healthSize - Math.round(healthSize * HEALTH_OVERLAP) - PAD)
			: healthSize + textGap;
		int nameHeight = showName ? lineHeight : 0;
		int[] smallDigits = digitExtent(graphics, nameFont);
		int killCountHeight = !killCountRow ? 0
			: killCountPlate ? smallDigits[0] - smallDigits[1] + textGap + badgePadY * 2 : lineHeight;

		// The timer's line is kept free from the start, at the bottom, so the orbs
		// don't shift about when a fight begins.
		int timerHeight = showTimer ? lineHeight : 0;
		int cellHeight = orbBox + healthHeight + nameHeight + killCountHeight + timerHeight;

		WikiLink wikiLink = config.wikiLink();
		boolean linked = wikiLink != WikiLink.OFF;
		// Over the bosses, an orb doesn't light up or explain itself under the
		// mouse: the mouse is there for the boss.
		Rectangle placed = overHeads ? CANVAS_ORIGIN : getBounds();
		Point mouse = overHeads || client.isMenuOpen() ? null : client.getMouseCanvasPosition();

		Player local = client.getLocalPlayer();
		Actor attacked = count > 1 && config.highlightTarget() && local != null ? local.getInteracting() : null;

		for (int i = 0; i < count; i++)
		{
			TrackedBoss boss = bosses.get(i);
			int cellX;
			int cellY;
			if (overHeads)
			{
				if (!findHead(boss))
				{
					orbXs[i] = OFF_SCREEN;
					orbYs[i] = OFF_SCREEN;
					continue;
				}

				// Sitting on the boss's head, and kept on screen when the boss is
				// tall or close enough that its head is off the top.
				cellX = Math.max(0, Math.min(client.getCanvasWidth() - cellWidth, boss.headX - cellWidth / 2));
				cellY = Math.max(0, boss.headY - cellHeight);
			}
			else
			{
				cellX = horizontal ? i * (cellWidth + spacing) : 0;
				cellY = horizontal ? 0 : i * (cellHeight + spacing);
			}
			int centreX = cellX + cellWidth / 2;
			int orbX = centreX - size / 2;
			int orbY = cellY + PAD;

			// An orb fades in when its boss turns up, and the orb of a boss that has
			// died fades out at the end of its stay.
			Composite previousComposite = graphics.getComposite();
			float alpha = 1;
			long present = now - boss.appearedAt;
			if (present < APPEAR_MS)
			{
				alpha = Math.max(0f, present / (float) APPEAR_MS);
			}

			long gone = boss.goneAt == 0 ? 0 : now - boss.goneAt;
			if (gone > boss.lingerMs - FADE_MS)
			{
				alpha *= Math.max(0f, (boss.lingerMs - gone) / (float) FADE_MS);
			}

			if (alpha < 1)
			{
				graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
			}

			// The colour follows the health as drawn, and blends from one band into
			// the next rather than switching.
			boolean waiting = respawns[i] >= 0;
			Color colour = blend(boss, waiting ? respawnColour() : colourFor(boss.shown), elapsed);
			if (waiting)
			{
				// Refilling as the respawn comes round, with the boss itself greyed back.
				double filled = 1 - respawns[i] / (double) boss.respawnMs;
				drawOrb(graphics, design, boss.skill, orbX, orbY, size, filled, filled, colour, WAITING_ICON);
			}
			else
			{
				drawOrb(graphics, design, boss.skill, orbX, orbY, size, boss.shown, boss.trail, colour, 1f);
			}

			drawEffects(graphics, boss, orbX, orbY, size, now, waiting);

			if (attacked != null && boss.npc == attacked)
			{
				Stroke previousStroke = graphics.getStroke();
				stroke(graphics, circle(orbX, orbY, size, -2f), 1.6f, TARGET_RING);
				graphics.setStroke(previousStroke);
			}

			orbXs[i] = placed.x + orbX;
			orbYs[i] = placed.y + orbY;

			if (mouse != null && mouse.getX() >= placed.x + orbX && mouse.getX() < placed.x + orbX + size
				&& mouse.getY() >= placed.y + orbY && mouse.getY() < placed.y + orbY + size)
			{
				// An orb that can be clicked lights up under the mouse to say so.
				if (linked)
				{
					drawHover(graphics, orbX, orbY, size);
				}

				tooltipManager.add(new Tooltip(tooltip(boss, killCounts[i], respawns[i], wikiLink)));
			}

			String killCount = killCountTexts[i];
			if (killCount != null && killCountPlace == KillCountPlace.ORB)
			{
				drawBadge(graphics, boss, killCount, nameFont, centreX, cellY + PAD + size / 2, size, cellX, cellY,
					now, killCountPlate);
			}

			int baseline = cellY + orbBox;
			if (healthTexts[i] != null)
			{
				baseline += healthHeight;
				drawHealth(graphics, healthTexts[i], numberFont, centreX, baseline, colour, boss.edge, plate);

				if (config.damageNumbers() && boss.change != null)
				{
					int width = numberMetrics.stringWidth(healthTexts[i]) - trailingSpace
						+ (plate ? platePadX * 2 : 0);
					drawDrift(graphics, boss.change, nameFont, centreX + width / 2 + 3, baseline - platePadY,
						baseline - platePadY - changeRise, now - boss.changeAt, CHANGE_MS,
						boss.changeHeal ? gainColour() : damageColour());
				}
			}
			if (names[i] != null)
			{
				baseline += nameHeight;
				drawOutlined(graphics, names[i], nameFont, centreX, baseline, config.textColour());
			}
			if (killCount != null && killCountRow)
			{
				baseline += killCountHeight;
				int width = nameMetrics.stringWidth(killCount);
				if (killCountPlate)
				{
					drawPlate(graphics, killCount, nameFont, centreX, baseline, config.killCountColour(),
						badgeEdgeColour(false), BADGE_FILL, badgePadX, badgePadY, 1f);
					width += badgePadX * 2;
				}
				else
				{
					drawOutlined(graphics, killCount, nameFont, centreX, baseline, config.killCountColour());
				}

				if (boss.killGain > 0 && boss.killAt != 0 && now - boss.killAt < GAIN_MS)
				{
					drawDrift(graphics, "+" + boss.killGain, nameFont, centreX + width / 2 + 3, baseline,
						baseline - gainRise, now - boss.killAt, GAIN_MS, gainColour());
				}
			}

			if (timers[i] != null)
			{
				baseline += timerHeight;
				drawOutlined(graphics, timers[i], nameFont, centreX, baseline, timerColour());
			}

			graphics.setComposite(previousComposite);
		}

		orbsClickable = !overHeads;
		setWikiTargets(linked ? targetsFor(bosses, count, size) : Collections.emptyList());
		if (overHeads)
		{
			return null;
		}

		return horizontal
			? new Dimension(count * cellWidth + (count - 1) * spacing, cellHeight + 2)
			: new Dimension(cellWidth, count * cellHeight + (count - 1) * spacing + 2);
	}

	/**
	 * Makes sure the per-orb lists are long enough for this many orbs.
	 */
	private void reserve(int count)
	{
		if (killCounts.length >= count)
		{
			return;
		}

		killCounts = new int[count];
		respawns = new long[count];
		orbXs = new int[count];
		orbYs = new int[count];
		healthTexts = new String[count];
		timers = new String[count];
		names = new String[count];
		killCountTexts = new String[count];
	}

	/**
	 * Where the orbs are for the mouse to find, which is the list from the last
	 * frame unless something has moved.
	 */
	private List<WikiTarget> targetsFor(List<TrackedBoss> bosses, int count, int size)
	{
		List<WikiTarget> current = wikiTargets;
		boolean unchanged = current.size() == count;
		for (int i = 0; unchanged && i < count; i++)
		{
			WikiTarget target = current.get(i);
			unchanged = target.bounds.x == orbXs[i] && target.bounds.y == orbYs[i] && target.bounds.width == size
				&& target.name.equals(bosses.get(i).name);
		}

		if (unchanged)
		{
			return current;
		}

		List<WikiTarget> targets = new ArrayList<>(count);
		for (int i = 0; i < count; i++)
		{
			TrackedBoss boss = bosses.get(i);
			targets.add(new WikiTarget(new Rectangle(orbXs[i], orbYs[i], size, size), boss.name, boss.countName,
				boss.npc.getId()));
		}

		return targets;
	}

	// What is written under an orb changes far less often than it is drawn, so
	// each piece of text is kept with its boss until the figure behind it moves.

	private static String respawnText(TrackedBoss boss, long seconds)
	{
		if (boss.respawnText == null || boss.respawnSeconds != seconds)
		{
			boss.respawnSeconds = seconds;
			boss.respawnText = formatTime(seconds);
		}

		return boss.respawnText;
	}

	private static String timerText(TrackedBoss boss, long seconds)
	{
		if (boss.timerText == null || boss.timerSeconds != seconds)
		{
			boss.timerSeconds = seconds;
			boss.timerText = formatTime(seconds);
		}

		return boss.timerText;
	}

	private static String killCountText(TrackedBoss boss, int killCount, boolean below)
	{
		if (boss.killCountText == null || boss.killCountShown != killCount || boss.killCountBelow != below)
		{
			boss.killCountShown = killCount;
			boss.killCountBelow = below;
			boss.killCountText = below ? formatKillCount(killCount) + " kc" : formatKillCount(killCount);
		}

		return boss.killCountText;
	}

	private static String fittedName(TrackedBoss boss, Font font, FontMetrics metrics, int maxWidth)
	{
		if (boss.fittedName == null || boss.fittedWidth != maxWidth || boss.fittedFont != font)
		{
			boss.fittedWidth = maxWidth;
			boss.fittedFont = font;
			boss.fittedName = fit(boss.name, metrics, maxWidth);
		}

		return boss.fittedName;
	}

	private Color timerColour()
	{
		Color text = config.textColour();
		if (!text.equals(timerFrom))
		{
			timerFrom = text;
			timerColour = withAlpha(text, 215);
		}

		return timerColour;
	}

	/**
	 * How long until a dead boss respawns in milliseconds, or -1 if it isn't one
	 * being waited on.
	 */
	private static long respawnLeft(TrackedBoss boss, long now)
	{
		if (boss.goneAt == 0 || boss.respawnMs <= 0)
		{
			return -1;
		}

		long left = boss.respawnMs - (now - boss.goneAt);
		return left > 0 ? left : -1;
	}

	/**
	 * What hovering over an orb says: the boss, how it stands, the player's record
	 * against it, and what a click will do.
	 */
	private String tooltip(TrackedBoss boss, int killCount, long respawnLeft, WikiLink wikiLink)
	{
		StringBuilder text = new StringBuilder(ColorUtil.wrapWithColorTag(boss.name, Color.YELLOW));
		if (respawnLeft >= 0)
		{
			text.append("</br>Respawns in ").append(formatTime((respawnLeft + 999) / 1000));
		}
		else if (boss.maximum > 0)
		{
			text.append("</br>Health: ").append(boss.current).append(" / ").append(boss.maximum);
		}
		else
		{
			text.append("</br>Health: ").append(Math.round(boss.fraction * 100)).append('%');
		}

		// Dusk's count is the Grotesque Guardians', so it says which.
		boolean own = boss.countName.equalsIgnoreCase(boss.name);
		if (killCount >= 0)
		{
			text.append("</br>").append(own ? "Kill count" : boss.countName).append(": ")
				.append(QuantityFormatter.formatNumber(killCount));
		}

		double best = plugin.personalBest(boss);
		if (best > 0)
		{
			text.append("</br>Personal best: ").append(formatBest(best));
		}

		if (wikiLink != WikiLink.OFF)
		{
			text.append("</br>").append(wikiLink == WikiLink.CLICK ? "Click" : "Right-click").append(" for the wiki");
		}

		return text.toString();
	}

	static String formatTime(long seconds)
	{
		return seconds / 60 + ":" + (seconds % 60 < 10 ? "0" : "") + seconds % 60;
	}

	/**
	 * A best time, to the hundredth of a second when it was recorded that finely.
	 */
	static String formatBest(double seconds)
	{
		long whole = (long) seconds;
		if (seconds == whole)
		{
			return formatTime(whole);
		}

		return String.format(Locale.ROOT, "%d:%05.2f", whole / 60, seconds - whole / 60 * 60);
	}

	/**
	 * Works out where a boss's orb is in its animations this frame: eases the
	 * drawn health towards the real reading, and notes a hit or a heal when the
	 * reading moves.
	 */
	private void animate(TrackedBoss boss, long now, double elapsed)
	{
		double target = Math.max(0, Math.min(1, boss.fraction));
		if (boss.shown < 0)
		{
			boss.appearedAt = now;
			boss.shown = target;
			boss.trail = target;
			boss.reacted = target;
			boss.reactedHealth = boss.maximum > 0 ? boss.current : -1;
			boss.quietChange = false;
			return;
		}

		if (Math.abs(target - boss.reacted) > SETTLED)
		{
			// The size of the change is only written out where it is the real figure,
			// not one worked back from the width of a health bar.
			int health = boss.maximum > 0 ? boss.current : -1;
			if (!boss.quietChange && boss.exact && health >= 0 && boss.reactedHealth >= 0
				&& health != boss.reactedHealth)
			{
				int difference = health - boss.reactedHealth;
				boss.change = (difference > 0 ? "+" : "") + difference;
				boss.changeHeal = difference > 0;
				boss.changeAt = now;
			}
			boss.reactedHealth = health;

			if (boss.quietChange)
			{
				boss.quietChange = false;
			}
			else if (target < boss.reacted)
			{
				boss.hitAt = now;
				boss.trail = Math.max(boss.trail, boss.shown);
				boss.trailHoldUntil = now + TRAIL_HOLD_MS;
			}
			else
			{
				boss.healAt = now;
			}

			boss.reacted = target;
		}

		boss.shown = glide(boss.shown, target, boss.shownSpeed, elapsed, GLIDE_MS);
		boss.shownSpeed = glideSpeed;
		if (boss.trail <= boss.shown)
		{
			boss.trail = boss.shown;
			boss.trailSpeed = 0;
		}
		else if (now >= boss.trailHoldUntil)
		{
			boss.trail = glide(boss.trail, boss.shown, boss.trailSpeed, elapsed, TRAIL_GLIDE_MS);
			boss.trailSpeed = glideSpeed;
		}
	}

	/**
	 * The colour to draw an orb in this frame, which closes on the colour it is
	 * heading for a little at a time.
	 */
	private static Color blend(TrackedBoss boss, Color target, double elapsed)
	{
		if (!boss.tinted)
		{
			boss.tinted = true;
			boss.red = target.getRed();
			boss.green = target.getGreen();
			boss.blue = target.getBlue();
		}
		else
		{
			double step = 1 - Math.exp(-elapsed / COLOUR_EASE_MS);
			boss.red += (target.getRed() - boss.red) * step;
			boss.green += (target.getGreen() - boss.green) * step;
			boss.blue += (target.getBlue() - boss.blue) * step;
		}

		// The same colour object serves until the colour actually moves.
		int red = (int) Math.round(boss.red);
		int green = (int) Math.round(boss.green);
		int blue = (int) Math.round(boss.blue);
		Color colour = boss.colour;
		if (colour == null || colour.getRed() != red || colour.getGreen() != green || colour.getBlue() != blue)
		{
			colour = new Color(red, green, blue);
			boss.colour = colour;
			boss.edge = withAlpha(colour, 220);
		}

		return colour;
	}

	/**
	 * Moves a value towards where it is going the way a damped spring would: it
	 * picks up speed, then slows into place, and carries its speed over when the
	 * target moves again mid-flight. That is what keeps a run of hits reading as
	 * one smooth fall rather than a string of lurches, which easing by a fixed
	 * share of the distance each frame does not: that starts every move at full
	 * tilt. The speed it ends up with is left in {@link #glideSpeed}.
	 *
	 * @param speed how fast the value was already moving, per millisecond
	 * @param time roughly how long the move should take, in milliseconds
	 */
	private double glide(double from, double to, double speed, double elapsed, double time)
	{
		double stiffness = 2 / time;
		double step = stiffness * elapsed;
		double decay = 1 / (1 + step + 0.48 * step * step + 0.235 * step * step * step);
		double offset = from - to;
		double push = (speed + stiffness * offset) * elapsed;
		double next = to + (offset + push) * decay;
		glideSpeed = (speed - stiffness * push) * decay;

		// Close enough is there, and it never carries on past where it was going.
		if (Math.abs(to - next) < SETTLED / 4 || (to > from) == (next > to))
		{
			glideSpeed = 0;
			return to;
		}

		return next;
	}

	/**
	 * How much bigger than usual the kill count badge is drawn: it swells and
	 * settles once when a kill is counted.
	 */
	private static double killPop(TrackedBoss boss, long now)
	{
		long age = now - boss.killAt;
		if (boss.killAt == 0 || age >= KILL_POP_MS)
		{
			return 1;
		}

		double progress = age / (double) KILL_POP_MS;
		return 1 + 0.5 * Math.sin(Math.PI * progress) * (1 - progress * 0.5);
	}

	/**
	 * The passing effects over an orb: a white flash when it is hit, a green glow
	 * when it heals, and a slow pulse while it is at critical health.
	 */
	private void drawEffects(Graphics2D graphics, TrackedBoss boss, int x, int y, int size, long now, boolean waiting)
	{
		long sinceHit = now - boss.hitAt;
		if (boss.hitAt != 0 && sinceHit < HIT_MS)
		{
			double fade = 1 - sinceHit / (double) HIT_MS;
			graphics.setColor(new Color(255, 255, 255, (int) (105 * fade * fade)));
			graphics.fill(circle(x, y, size, 1));
		}

		long sinceHeal = now - boss.healAt;
		if (boss.healAt != 0 && sinceHeal < HEAL_MS)
		{
			double fade = 1 - sinceHeal / (double) HEAL_MS;
			graphics.setColor(withAlpha(healColour(), (int) (120 * fade)));
			graphics.fill(circle(x, y, size, 1));
		}

		if (!waiting && boss.fraction > 0 && boss.fraction * 100 < config.lowThreshold())
		{
			double beat = 0.5 + 0.5 * Math.sin(now % PULSE_MS / (double) PULSE_MS * 2 * Math.PI);
			Color critical = safeColours ? SAFE_CRITICAL : config.criticalColour();
			graphics.setColor(withAlpha(critical, (int) (52 * beat)));
			graphics.fill(circle(x, y, size, 1));

			Stroke previous = graphics.getStroke();
			stroke(graphics, circle(x, y, size, -0.5f), 2f, withAlpha(critical, 60 + (int) (180 * beat)));
			graphics.setStroke(previous);
		}
	}

	/**
	 * A bright edge and a faint wash over the orb the mouse is on.
	 */
	private static void drawHover(Graphics2D graphics, int x, int y, int size)
	{
		Stroke previous = graphics.getStroke();
		graphics.setColor(new Color(255, 255, 255, 38));
		graphics.fill(circle(x, y, size, 1));
		stroke(graphics, circle(x, y, size, 0.5f), 1.6f, new Color(255, 255, 255, 230));
		graphics.setStroke(previous);
	}

	/**
	 * A short piece of text that drifts from one baseline up to another and fades
	 * out: the "+1" beside a kill count, or a hit beside the health number.
	 */
	private void drawDrift(Graphics2D graphics, String text, Font font, int left, int from, int to, long age,
		int life, Color colour)
	{
		if (age < 0 || age >= life)
		{
			return;
		}

		// Solid for the first part of its life, so it can be read, then fading.
		double progress = age / (double) life;
		float alpha = (float) Math.min(1, (1 - progress) * 1.8);
		int baseline = (int) Math.round(from + (to - from) * (1 - (1 - progress) * (1 - progress)));

		Composite previous = graphics.getComposite();
		float base = previous instanceof AlphaComposite ? ((AlphaComposite) previous).getAlpha() : 1f;
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, base * alpha));

		int width = graphics.getFontMetrics(font).stringWidth(text);
		drawOutlined(graphics, text, font, left + width / 2, baseline, colour);
		graphics.setComposite(previous);
	}

	private void drawOrb(Graphics2D graphics, OrbDesign design, HiscoreSkill skill, int x, int y, int size,
		double fraction, double trail, Color colour, float iconAlpha)
	{
		int iconSpace = art.draw(graphics, design, x, y, size, fraction, trail, colour, config.backgroundColour());
		drawIcon(graphics, skill, x + size / 2, y + size / 2, iconSpace, iconAlpha);
	}

	private static Shape circle(int x, int y, int size, float inset)
	{
		return new Ellipse2D.Float(x + inset, y + inset, size - inset * 2, size - inset * 2);
	}

	private static void stroke(Graphics2D graphics, Shape shape, float width, Color colour)
	{
		int tenths = Math.max(0, Math.min(STROKES.length - 1, Math.round(width * 10)));
		BasicStroke stroke = STROKES[tenths];
		if (stroke == null)
		{
			stroke = new BasicStroke(tenths / 10f);
			STROKES[tenths] = stroke;
		}

		graphics.setStroke(stroke);
		graphics.setColor(colour);
		graphics.draw(shape);
	}

	private void drawIcon(Graphics2D graphics, HiscoreSkill skill, int centreX, int centreY, int space, float alpha)
	{
		BufferedImage icon = icon(skill, Math.max(8, Math.round(space * ICON_SHARE)));
		if (icon == null)
		{
			return;
		}

		Composite previous = graphics.getComposite();
		if (alpha < 1)
		{
			float base = previous instanceof AlphaComposite ? ((AlphaComposite) previous).getAlpha() : 1f;
			graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, base * alpha));
		}

		graphics.drawImage(icon, centreX - icon.getWidth() / 2, centreY - icon.getHeight() / 2, null);
		graphics.setComposite(previous);
	}

	/**
	 * The health number, on a small dark plate edged in the health colour when
	 * plates are on, or outlined straight over the scenery when they are off.
	 * Either way it ends at the given bottom edge.
	 */
	private void drawHealth(Graphics2D graphics, String text, Font font, int centreX, int bottom, Color band,
		Color edge, boolean plated)
	{
		Color number = config.healthColoured() ? band : config.textColour();
		if (plated)
		{
			drawPlate(graphics, text, font, centreX, bottom, number, edge, PLATE_FILL, platePadX, platePadY, 1.2f);
		}
		else
		{
			drawOutlined(graphics, text, font, centreX, bottom - 1 + digitExtent(graphics, font)[1], number);
		}
	}

	/**
	 * A number on a dark pill with a coloured edge, sitting on the given bottom
	 * edge. The health number and the kill count are both drawn this way.
	 */
	private void drawPlate(Graphics2D graphics, String text, Font font, int centreX, int bottom, Color number,
		Color edge, Color fill, int padX, int padY, float edgeWidth)
	{
		int[] digits = digitExtent(graphics, font);
		int width = graphics.getFontMetrics(font).stringWidth(text) - trailingSpace + padX * 2;
		int height = digits[0] - digits[1] + padY * 2;
		int left = centreX - width / 2;
		pill.setRoundRect(left, bottom - height, width, height, height, height);

		graphics.setColor(fill);
		graphics.fill(pill);
		Stroke previous = graphics.getStroke();
		stroke(graphics, pill, edgeWidth, edge);
		graphics.setStroke(previous);

		Font previousFont = graphics.getFont();
		graphics.setFont(font);
		graphics.setColor(number);
		graphics.drawString(text, left + padX, bottom - padY + digits[1]);
		graphics.setFont(previousFont);
	}

	/**
	 * The kill count at the orb's top left, on a small pill or written straight
	 * over the orb. That corner is the last part of a health ring to matter: it
	 * only empties in the first few hits. It also plays its part in marking a
	 * kill, swelling as the count goes up with a "+1" beside it.
	 */
	private void drawBadge(Graphics2D graphics, TrackedBoss boss, String text, Font font, int centreX, int centreY,
		int size, int minX, int minY, long now, boolean plated)
	{
		double scale = killPop(boss, now);
		int[] digits = digitExtent(graphics, font);
		int textWidth = graphics.getFontMetrics(font).stringWidth(text);
		int width = textWidth - trailingSpace + badgePadX * 2;
		int height = digits[0] - digits[1] + badgePadY * 2;
		int reach = (int) Math.round(size / 2.0 * BADGE_OFFSET);
		int x = Math.max(minX, centreX - reach - width / 2);
		int y = Math.max(minY, centreY - reach - height / 2);
		int level = y + badgePadY + digits[0];

		// Only a count in the middle of its swell needs the drawing scaled.
		AffineTransform previousTransform = null;
		if (scale != 1)
		{
			previousTransform = graphics.getTransform();
			double middleX = x + width / 2.0;
			double middleY = y + height / 2.0;
			graphics.translate(middleX, middleY);
			graphics.scale(scale, scale);
			graphics.translate(-middleX, -middleY);
		}

		Color count = config.killCountColour();
		if (plated)
		{
			pill.setRoundRect(x, y, width, height, height, height);
			graphics.setColor(BADGE_FILL);
			graphics.fill(pill);
			Stroke previous = graphics.getStroke();
			stroke(graphics, pill, 1f, badgeEdgeColour(scale != 1));
			graphics.setStroke(previous);

			Font previousFont = graphics.getFont();
			graphics.setFont(font);
			graphics.setColor(count);
			graphics.drawString(text, x + badgePadX, level);
			graphics.setFont(previousFont);
		}
		else
		{
			drawOutlined(graphics, text, font, x + badgePadX + textWidth / 2, level, count);
		}

		if (previousTransform != null)
		{
			graphics.setTransform(previousTransform);
		}

		// The count is at the top of its cell, so the "+1" comes up from below to
		// settle beside it rather than rising out into whatever is above.
		if (boss.killAt != 0 && boss.killGain > 0 && now - boss.killAt < GAIN_MS)
		{
			drawDrift(graphics, "+" + boss.killGain, font, x + width + 2, level + gainRise, level,
				now - boss.killAt, GAIN_MS, gainColour());
		}
	}

	/**
	 * The edge of a kill count plate: a shade of the kill count colour, brighter
	 * while a kill is being marked.
	 */
	private Color badgeEdgeColour(boolean lit)
	{
		Color count = config.killCountColour();
		if (!count.equals(badgeColour))
		{
			badgeColour = count;
			badgeEdge = withAlpha(count, 170);
			badgeEdgeLit = withAlpha(count, 255);
		}

		return lit ? badgeEdgeLit : badgeEdge;
	}

	/**
	 * How far above the baseline a font's digits start and stop. The RuneScape
	 * fonts report an ascent well clear of their digits and sit them above the
	 * baseline, so a number placed by the font's own metrics ends up off centre.
	 */
	private int[] digitExtent(Graphics2D graphics, Font font)
	{
		int[] extent = digitExtents.get(font);
		if (extent == null)
		{
			Rectangle2D bounds = font.createGlyphVector(graphics.getFontRenderContext(), "0123456789")
				.getVisualBounds();
			extent = new int[]{(int) Math.round(-bounds.getMinY()), (int) Math.round(-bounds.getMaxY())};
			digitExtents.put(font, extent);
		}

		return extent;
	}

	/**
	 * Short enough to fit a badge: grouped digits up to 9,999, then thousands to
	 * one decimal place.
	 */
	static String formatKillCount(int killCount)
	{
		return killCount < 10_000
			? QuantityFormatter.formatNumber(killCount)
			: killCount / 1000 + "." + killCount % 1000 / 100 + "k";
	}

	private void drawOutlined(Graphics2D graphics, String text, Font font, int centreX, int baseline, Color colour)
	{
		Font previous = graphics.getFont();
		graphics.setFont(font);

		int x = centreX - graphics.getFontMetrics().stringWidth(text) / 2;

		// A full outline rather than a drop shadow, so it holds up over any scenery.
		graphics.setColor(outlineColour);
		for (int[] step : outlineSteps)
		{
			graphics.drawString(text, x + step[0], baseline + step[1]);
		}

		graphics.setColor(colour);
		graphics.drawString(text, x, baseline);
		graphics.setFont(previous);
	}

	private String healthText(TrackedBoss boss)
	{
		HealthText style = config.healthText();
		boolean percentage = style == HealthText.PERCENTAGE || boss.maximum <= 0;

		// While the orb is still draining, the number runs down with it.
		int value;
		if (percentage)
		{
			value = (int) Math.round((boss.shown >= 0 ? boss.shown : boss.fraction) * 100);
		}
		else
		{
			value = boss.shown >= 0 && Math.abs(boss.shown - boss.fraction) > SETTLED
				? (int) Math.round(boss.shown * boss.maximum) : boss.current;
		}

		int maximum = percentage ? -1 : boss.maximum;
		if (boss.healthText == null || boss.healthValue != value || boss.healthMaximum != maximum
			|| boss.healthStyle != style)
		{
			boss.healthValue = value;
			boss.healthMaximum = maximum;
			boss.healthStyle = style;
			boss.healthText = percentage ? value + "%"
				: style == HealthText.BOTH ? value + "/" + maximum : String.valueOf(value);
		}

		return boss.healthText;
	}

	private Color colourFor(double fraction)
	{
		double percent = fraction * 100;
		if (percent >= config.highThreshold())
		{
			return safeColours ? SAFE_HIGH : config.highColour();
		}

		if (percent >= config.midThreshold())
		{
			return safeColours ? SAFE_MID : config.midColour();
		}

		if (percent >= config.lowThreshold())
		{
			return safeColours ? SAFE_LOW : config.lowColour();
		}

		return safeColours ? SAFE_CRITICAL : config.criticalColour();
	}

	private Color gainColour()
	{
		return safeColours ? SAFE_GAIN : GAIN;
	}

	private Color damageColour()
	{
		return safeColours ? SAFE_DAMAGE : DAMAGE;
	}

	private Color healColour()
	{
		return safeColours ? SAFE_GAIN : HEAL_GLOW;
	}

	private Color respawnColour()
	{
		return safeColours ? SAFE_RESPAWN : RESPAWN;
	}

	/**
	 * A boss's icon with its longest side scaled to the given length, outlined.
	 *
	 * <p>The icons are pixel art, which stretches badly by anything but a whole
	 * number. So it is first enlarged by the next whole number up, which keeps its
	 * edges hard, and then eased down to size, which only has to shrink it a
	 * little. The outline goes on last so it stays one crisp pixel at any size.
	 */
	private BufferedImage icon(HiscoreSkill skill, int longest)
	{
		int spriteId = skill.getSpriteId();
		if (spriteId < 0)
		{
			return null;
		}

		// The few icons on screen are looked for by hand first, which a frame can
		// do without making anything.
		int key = spriteId * 1024 + longest;
		for (int i = 0; i < ICONS_TO_HAND; i++)
		{
			if (iconKeys[i] == key && iconsToHand[i] != null)
			{
				return iconsToHand[i];
			}
		}

		BufferedImage cached = icons.get(key);
		if (cached != null)
		{
			keepToHand(key, cached);
			return cached;
		}

		BufferedImage sprite = sprites.get(spriteId);
		if (sprite == null)
		{
			sprite = spriteManager.getSprite(spriteId, 0);
			if (sprite == null)
			{
				return null;
			}

			sprites.put(spriteId, sprite);
		}

		// Two pixels of the length are the outline's.
		double scale = Math.max(0.2, (longest - 2) / (double) Math.max(sprite.getWidth(), sprite.getHeight()));
		int whole = Math.max(1, (int) Math.ceil(scale - 1e-6));
		int width = Math.max(1, (int) Math.round(sprite.getWidth() * scale));
		int height = Math.max(1, (int) Math.round(sprite.getHeight() * scale));

		BufferedImage scaled = redraw(sprite, sprite.getWidth() * whole, sprite.getHeight() * whole,
			RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		if (scaled.getWidth() != width || scaled.getHeight() != height)
		{
			scaled = redraw(scaled, width, height, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		}

		BufferedImage outlined = ImageUtil.outlineImage(scaled, Color.BLACK);
		if (icons.size() >= ICON_CACHE_LIMIT)
		{
			icons.clear();
		}

		icons.put(key, outlined);
		keepToHand(key, outlined);
		return outlined;
	}

	private void keepToHand(int key, BufferedImage icon)
	{
		iconKeys[nextIcon] = key;
		iconsToHand[nextIcon] = icon;
		nextIcon = (nextIcon + 1) % ICONS_TO_HAND;
	}

	private static BufferedImage redraw(BufferedImage source, int width, int height, Object interpolation)
	{
		BufferedImage redrawn = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = redrawn.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, interpolation);
		graphics.drawImage(source, 0, 0, width, height, null);
		graphics.dispose();
		return redrawn;
	}

	private static String fit(String text, FontMetrics metrics, int maxWidth)
	{
		if (metrics.stringWidth(text) <= maxWidth)
		{
			return text;
		}

		String ellipsis = "...";
		int end = text.length();
		while (end > 1 && metrics.stringWidth(text.substring(0, end) + ellipsis) > maxWidth)
		{
			end--;
		}

		return text.substring(0, end).trim() + ellipsis;
	}

	private static Color withAlpha(Color colour, int alpha)
	{
		return new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), Math.max(0, Math.min(255, alpha)));
	}
}

package com.bossorbs;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
