@Slf4j
@PluginDescriptor(
	name = "Boss Orbs",
	configName = "bossorbs",
	description = "Shows each nearby boss as an orb with its hiscores icon, draining as the boss loses health",
	tags = {"boss", "health", "hp", "orb", "pvm", "hiscores", "overlay", "hud"}
)
public class BossOrbsPlugin extends Plugin
{
	/**
	 * How far the game's own health display may disagree with the boss's health
	 * bar before it is taken to be showing something else.
	 */
	private static final double HUD_TOLERANCE = 0.08;

	/** Where RuneLite's Chat Commands plugin keeps the kill counts and best times it reads from chat. */
	private static final String KILLCOUNT_GROUP = "killcount";
	private static final String PERSONAL_BEST_GROUP = "personalbest";

	/**
	 * A limit on how many orbs are drawn, which is only there to keep a crowd of
	 * bosses from covering the screen. Every boss nearby gets an orb up to that.
	 */
	private static final int MOST_ORBS = 8;

	/**
	 * The sprites the game builds its wider overhead health bars from, which are
	 * the ones bosses tend to have. The standard small bar is left alone: players
	 * and ordinary monsters use it, and there is no hiding it for a boss alone.
	 */
	private static final int[] WIDE_BAR_SPRITES = {
		SpriteID.StandardHealth40.FRONT, SpriteID.StandardHealth40.BACK,
		SpriteID.StandardHealth50.FRONT, SpriteID.StandardHealth50.BACK,
		SpriteID.StandardHealth60.FRONT, SpriteID.StandardHealth60.BACK,
		SpriteID.StandardHealth70.FRONT, SpriteID.StandardHealth70.BACK,
		SpriteID.StandardHealth80.FRONT, SpriteID.StandardHealth80.BACK,
		SpriteID.StandardHealth90.FRONT, SpriteID.StandardHealth90.BACK,
		SpriteID.StandardHealth100.FRONT, SpriteID.StandardHealth100.BACK,
		SpriteID.StandardHealth120.FRONT, SpriteID.StandardHealth120.BACK,
		SpriteID.StandardHealth140.FRONT, SpriteID.StandardHealth140.BACK,
		SpriteID.StandardHealth160.FRONT, SpriteID.StandardHealth160.BACK,
	};

	/** How long past its respawn time a dead boss's orb waits for it before giving up. */
	private static final int RESPAWN_GRACE_MS = 1500;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private BossOrbsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BossOrbsOverlay overlay;

	@Inject
	private BossWorldOverlay worldOverlay;

	@Inject
	private BossCatalogue catalogue;

	@Inject
	private NPCManager npcManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private HiscoreClient hiscoreClient;

	@Inject
	private MouseManager mouseManager;

	/** Bosses in the scene, in the order they appeared, which is the order they are drawn in. */
	private final Map<NPC, TrackedBoss> bosses = new LinkedHashMap<>();

	private int lastHudNpc = -1;

	/** Bosses that have just died and left the scene, kept briefly so the kill can be marked on their orb. */
	private final List<TrackedBoss> departed = new ArrayList<>();

	/** The bosses to draw, refilled each frame rather than made anew. */
	private final List<TrackedBoss> visible = new ArrayList<>();

	/** Kill counts read from chat since the plugin started, which are newer than anything else. */
	private final Map<String, Integer> chatKillCounts = new HashMap<>();

	/** Kill counts and best times already looked up, so the overlay isn't reading config every frame. */
	private final Map<String, Integer> killCounts = new HashMap<>();
	private final Map<String, Double> personalBests = new HashMap<>();

	/** Set from whichever thread a kill count changes on; acted on at the next lookup. */
	private volatile boolean killCountsStale;

	/** Whether the setting to hide the game's own boss health bar is on, kept here as it is read every frame. */
	private volatile boolean replacingBars;

	/** Whether that bar is hidden by this plugin, and so is this plugin's to put back. */
	private boolean gameBarHidden;

	/**
	 * The blank sprites standing in for the game's wide overhead health bars while
	 * a boss is about, and whatever each one took the place of, so that another
	 * plugin's restyled bar is handed back rather than lost.
	 */
	private final Map<Integer, SpritePixels> blankBars = new HashMap<>();
	private final Map<Integer, SpritePixels> displacedBars = new HashMap<>();
	private boolean overheadBarsHidden;

	/** Kill counts from the hiscores, as they stood when the player logged in. */
	private volatile Map<HiscoreSkill, Integer> hiscoreKillCounts = Collections.emptyMap();

	/** The name the hiscores were last asked about, so each login asks once. */
	private volatile String hiscoreName;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(worldOverlay);
		mouseManager.registerMouseListener(overlay.wikiClicks);
		clientThread.invokeLater(this::reseed);
		replacingBars = config.replaceBar();
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(worldOverlay);
		mouseManager.unregisterMouseListener(overlay.wikiClicks);
		replacingBars = false;
		clientThread.invoke(() ->
		{
			restoreGameBar();
			applyOverheadBars(false);
		});
		bosses.clear();
		departed.clear();
		killCounts.clear();
		personalBests.clear();
		chatKillCounts.clear();
		hiscoreKillCounts = Collections.emptyMap();
		hiscoreName = null;
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		consider(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		TrackedBoss boss = bosses.remove(npc);
		if (boss == null || !(npc.isDead() || boss.fraction <= 0))
		{
			return;
		}

		// A dead boss's orb stays to mark the kill, and for one that respawns on a
		// timer, to count down to it.
		int respawn = config.respawnTimer() ? RespawnTimes.of(boss.name) : 0;
		boss.fraction = 0;
		if (boss.maximum > 0)
		{
			boss.current = 0;
		}

		long now = System.currentTimeMillis();
		boss.goneAt = now;
		if (boss.fightEnd == 0 && boss.fightStart != 0)
		{
			boss.fightEnd = now;
		}

		boss.respawnMs = respawn;
		boss.lingerMs = respawn > 0 ? respawn + RESPAWN_GRACE_MS : TrackedBoss.LINGER_MS;
		departed.add(boss);
	}

	/**
	 * Keeps the game's own boss health bar hidden while orbs are standing in for
	 * the health bars.
	 *
	 * <p>It has to be done every frame. The game redraws that bar from a script of
	 * its own as the fight goes on, and shows it again each time, so hiding it once
	 * - or once a tick - lasts no longer than the next redraw.
	 */
	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (!replacingBars)
		{
			return;
		}

		Widget bar = client.getWidget(InterfaceID.HpbarHud.UNIVERSE);
		if (bar != null && !bar.isSelfHidden())
		{
			bar.setHidden(true);
			if (!gameBarHidden)
			{
				gameBarHidden = true;
				log.debug("Hid the game's boss health bar");
			}
		}
	}

	/**
	 * Takes up the setting for hiding the game's boss health bar, and puts the bar
	 * back when it has been turned off.
	 */
	private void applyGameBar()
	{
		replacingBars = config.replaceBar();
		if (!replacingBars)
		{
			restoreGameBar();
		}

		applyOverheadBars(replacingBars && !bosses.isEmpty());
	}

	/**
	 * Hides or shows the game's wide overhead health bars, by swapping the sprites
	 * they are built from for blank ones. They are only hidden while a boss with an
	 * orb is about, because the swap takes in every monster with a bar that size.
	 */
	private void applyOverheadBars(boolean hide)
	{
		if (hide == overheadBarsHidden)
		{
			return;
		}

		overheadBarsHidden = hide;
		Map<Integer, SpritePixels> overrides = client.getSpriteOverrides();
		if (hide)
		{
			for (int spriteId : WIDE_BAR_SPRITES)
			{
				SpritePixels blank = blank(spriteId);
				if (blank != null)
				{
					blankBars.put(spriteId, blank);
					displacedBars.put(spriteId, overrides.put(spriteId, blank));
				}
			}
		}
		else
		{
			for (Map.Entry<Integer, SpritePixels> entry : blankBars.entrySet())
			{
				// Only what is still this plugin's is taken back out.
				Integer spriteId = entry.getKey();
				if (overrides.get(spriteId) == entry.getValue())
				{
					SpritePixels displaced = displacedBars.get(spriteId);
					if (displaced != null)
					{
						overrides.put(spriteId, displaced);
					}
					else
					{
						overrides.remove(spriteId);
					}
				}
			}

			blankBars.clear();
			displacedBars.clear();
		}

		// The client keeps assembled health bars, so a swapped sprite isn't seen
		// until those are thrown away.
		client.resetHealthBarCaches();
		log.debug("Overhead health bars {}", hide ? "hidden" : "put back");
	}

	/**
	 * A fully transparent sprite the size of one of the game's.
	 */
	private SpritePixels blank(int spriteId)
	{
		SpritePixels[] sprites = client.getSprites(client.getIndexSprites(), spriteId, 0);
		if (sprites == null || sprites.length == 0 || sprites[0] == null)
		{
			return null;
		}

		int width = sprites[0].getWidth();
		int height = sprites[0].getHeight();
		return client.createSpritePixels(new int[width * height], width, height);
	}

	/**
	 * Shows the game's boss health bar again, if this plugin hid it and the game
	 * still has a boss to show on it. With no boss the bar is the game's to keep
	 * hidden.
	 */
	private void restoreGameBar()
	{
		if (!gameBarHidden)
		{
			return;
		}

		gameBarHidden = false;
		Widget bar = client.getWidget(InterfaceID.HpbarHud.UNIVERSE);
		if (bar != null && client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC) != -1)
		{
			bar.setHidden(false);
			log.debug("Put the game's boss health bar back");
		}
	}

	/**
	 * Right-clicking an orb offers the boss's wiki page and its strategy guide.
	 * The entries are added here rather than through the overlay's own menu,
	 * which RuneLite only shows while Shift is held.
	 */
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (config.wikiLink() == WikiLink.OFF)
		{
			return;
		}

		Point mouse = client.getMouseCanvasPosition();
		WikiTarget target = mouse == null ? null : overlay.targetAt(mouse.getX(), mouse.getY());
		if (target == null)
		{
			return;
		}

		// Added last, the boss's own page ends up on top.
		String colouredName = ColorUtil.wrapWithColorTag(target.name, Color.YELLOW);
		String strategies = target.strategiesUrl();
		if (strategies != null)
		{
			client.getMenu().createMenuEntry(-1)
				.setOption("Strategies")
				.setTarget(colouredName)
				.setType(MenuAction.RUNELITE)
				.onClick(entry -> LinkBrowser.browse(strategies));
		}

		client.getMenu().createMenuEntry(-1)
			.setOption("Wiki")
			.setTarget(colouredName)
			.setType(MenuAction.RUNELITE)
			.onClick(entry -> LinkBrowser.browse(target.url()));
	}

	/**
	 * A kill count from chat is the newest there is, and its arrival is the moment
	 * to mark the kill on the boss's orb.
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		KillCountMessage counted = KillCountMessage.parse(event.getMessage());
		if (counted == null)
		{
			return;
		}

		String name = counted.boss;
		int killCount = counted.count;
		HiscoreSkill skill = catalogue.match(name);
		String key = BossCatalogue.key(skill != null ? skill.getName() : name);

		long now = System.currentTimeMillis();
		for (TrackedBoss boss : bosses.values())
		{
			markKill(boss, key, killCount, now);
		}
		for (TrackedBoss boss : departed)
		{
			markKill(boss, key, killCount, now);
		}

		chatKillCounts.put(key, killCount);
		killCountsStale = true;
		log.debug("Kill count for {} is now {}", name, killCount);
	}

	private void markKill(TrackedBoss boss, String key, int killCount, long now)
	{
		if (BossCatalogue.key(boss.countName).equals(key))
		{
			int before = killCount(boss);
			boss.killAt = now;
			boss.killGain = before >= 0 && killCount > before ? killCount - before : 1;
		}
	}

	/**
	 * Several bosses change form mid-fight or wake from a version that can't be
	 * attacked, which arrives as a change to the same NPC rather than a new one.
	 */
	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		NPC npc = event.getNpc();
		TrackedBoss previous = bosses.get(npc);
		if (previous != null && catalogue.match(npc.getName()) == previous.skill && isFightable(npc))
		{
			// Same boss in a new form: keep its orb, and its place in the row.
			return;
		}

		bosses.remove(npc);
		consider(npc);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING || state == GameState.HOPPING || state == GameState.LOGIN_SCREEN)
		{
			bosses.clear();
			departed.clear();
			if (state == GameState.LOGIN_SCREEN)
			{
				// The hiscores catch up when a player logs out, so ask again next login.
				hiscoreName = null;
			}
		}
		else if (state == GameState.LOGGED_IN)
		{
			// Spawn events don't always fire for NPCs that survive a region load.
			clientThread.invokeLater(this::reseed);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		String group = event.getGroup();
		if (KILLCOUNT_GROUP.equals(group) || PERSONAL_BEST_GROUP.equals(group))
		{
			killCountsStale = true;
		}
		else if (BossOrbsConfig.GROUP.equals(group))
		{
			clientThread.invoke(this::applyGameBar);
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		killCountsStale = true;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		Player local = client.getLocalPlayer();
		String name = local == null ? null : local.getName();
		if (name != null && !name.equals(hiscoreName))
		{
			hiscoreName = name;
			lookUpHiscores(name);
		}

		applyOverheadBars(replacingBars && !bosses.isEmpty());

		if (bosses.isEmpty())
		{
			return;
		}

		int hudNpc = client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC);
		int hudBase = client.getVarbitValue(VarbitID.HPBAR_HUD_BASEHP);
		int hudHealth = client.getVarbitValue(VarbitID.HPBAR_HUD_HP);
		if (hudNpc != lastHudNpc)
		{
			lastHudNpc = hudNpc;
			log.debug("Game health display now on npc {} at {}/{}", hudNpc, hudHealth, hudBase);
		}

		for (TrackedBoss boss : bosses.values())
		{
			refresh(boss, hudNpc, hudHealth, hudBase);
		}
	}

	private void reseed()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			consider(npc);
		}
	}

	private void consider(NPC npc)
	{
		if (npc == null || bosses.containsKey(npc))
		{
			return;
		}

		HiscoreSkill skill = catalogue.match(npc.getName());
		if (skill == null || !isFightable(npc))
		{
			return;
		}

		// With the boss back, the orb that was counting down to it has done its job.
		String name = Text.removeTags(npc.getName());
		departed.removeIf(gone -> gone.name.equals(name));

		bosses.put(npc, new TrackedBoss(npc, skill, name, skill.getName()));
		log.debug("Tracking {} (npc {}) as {}", name, npc.getId(), skill.getName());
	}

	/**
	 * Bosses often exist in a form that can't be fought - asleep, on a throne,
	 * part of the scenery before the fight. Those have no combat level, and an orb
	 * for one would only sit there full.
	 */
	private static boolean isFightable(NPC npc)
	{
		NPCComposition composition = npc.getTransformedComposition();
		return composition != null && composition.getCombatLevel() > 0;
	}

	private void refresh(TrackedBoss boss, int hudNpc, int hudHealth, int hudBase)
	{
		NPC npc = boss.npc;
		int ratio = npc.getHealthRatio();
		int scale = npc.getHealthScale();
		Integer known = npcManager.getHealth(npc.getId());
		boolean wasExact = boss.exact;

		if (known != null && boss.maximum < 0)
		{
			boss.maximum = known;
			boss.current = known;
		}

		// The game only sends a health bar while a fight is going on. With none to
		// read, the last reading stands.
		if (ratio >= 0 && scale > 0)
		{
			boss.fraction = Math.min(1, ratio / (double) scale);
			boss.exact = false;
			if (known != null)
			{
				boss.maximum = known;
				boss.current = estimate(ratio, scale, known);
			}

			// The game's own health display carries exact hitpoints, but only for
			// one NPC at a time, and it keeps its last value after a fight. It is
			// used only when it is on this boss and agrees with this boss's bar.
			if (hudNpc == npc.getId() && hudBase > 0 && hudHealth >= 0 && hudHealth <= hudBase
				&& Math.abs(hudHealth / (double) hudBase - boss.fraction) <= Math.max(HUD_TOLERANCE, 1.5 / scale))
			{
				boss.maximum = hudBase;
				boss.current = hudHealth;
				boss.fraction = hudHealth / (double) hudBase;
				boss.exact = true;
			}

			// Swapping between the bar and the exact figure nudges the reading a
			// little either way, which is neither a hit nor a heal.
			if (boss.exact != wasExact)
			{
				boss.quietChange = true;
			}
		}

		if (boss.fraction < 1 && !boss.damaged)
		{
			boss.damaged = true;
			boss.fightStart = System.currentTimeMillis();
		}

		if (npc.isDead())
		{
			boss.fraction = 0;
			if (boss.maximum > 0)
			{
				boss.current = 0;
			}

			if (boss.fightEnd == 0 && boss.fightStart != 0)
			{
				boss.fightEnd = System.currentTimeMillis();
			}
		}
	}

	/**
	 * The health bar is a coarse fraction, so hitpoints are recovered from the
	 * range of values that fraction could stand for - the same sum RuneLite's own
	 * opponent information uses.
	 */
	static int estimate(int ratio, int scale, int maximum)
	{
		if (ratio <= 0)
		{
			return 0;
		}

		if (scale <= 1)
		{
			return maximum;
		}

		int low = ratio > 1 ? (maximum * (ratio - 1) + scale - 2) / (scale - 1) : 1;
		int high = Math.min((maximum * ratio - 1) / (scale - 1), maximum);
		return (low + high + 1) / 2;
	}

	/**
	 * Fetches the player's own hiscores for their kill counts. These are complete
	 * but only as recent as the last logout, so they are the floor that the counts
	 * read from chat during play sit on top of.
	 */
	private void lookUpHiscores(String name)
	{
		HiscoreEndpoint endpoint = HiscoreEndpoint.fromWorldTypes(client.getWorldType());
		hiscoreClient.lookupAsync(name, endpoint).whenComplete((result, failure) ->
		{
			if (result == null || !name.equals(hiscoreName))
			{
				log.debug("No hiscores kill counts for this login", failure);
				return;
			}

			hiscoreKillCounts = bossKillCounts(result);
			killCountsStale = true;
			log.debug("Read {} boss kill counts from the hiscores", hiscoreKillCounts.size());
		});
	}

	private static Map<HiscoreSkill, Integer> bossKillCounts(HiscoreResult result)
	{
		Map<HiscoreSkill, Integer> counts = new EnumMap<>(HiscoreSkill.class);
		for (Map.Entry<HiscoreSkill, Skill> entry : result.getSkills().entrySet())
		{
			if (entry.getKey().getType() == HiscoreSkillType.BOSS && entry.getValue().getLevel() > 0)
			{
				counts.put(entry.getKey(), entry.getValue().getLevel());
			}
		}

		return counts;
	}

	/**
	 * The player's kill count for a boss, or -1 if none is on record: the highest
	 * of the hiscores, what has been read from chat this session, and what Chat
	 * Commands has on file. Chat Commands files each count under the name in the
	 * game's message, which mostly is the hiscores name in lower case, sometimes
	 * without its leading "the".
	 */
	int killCount(TrackedBoss boss)
	{
		freshen();
		Integer killCount = killCounts.get(boss.countName);
		if (killCount == null)
		{
			killCount = storedKillCount(boss.countName);
			killCounts.put(boss.countName, killCount);
		}

		return killCount;
	}

	/**
	 * The player's best time for a boss in seconds, or -1 if none is on record.
	 */
	double personalBest(TrackedBoss boss)
	{
		freshen();
		return personalBests.computeIfAbsent(boss.countName, this::storedPersonalBest);
	}

	private void freshen()
	{
		if (killCountsStale)
		{
			killCountsStale = false;
			killCounts.clear();
			personalBests.clear();
		}
	}

	private int storedKillCount(String countName)
	{
		String name = filedName(countName);
		int best = Math.max(filedKillCount(name), chatKillCounts.getOrDefault(BossCatalogue.key(countName), -1));

		HiscoreSkill ranked = catalogue.hiscore(countName);
		if (ranked != null)
		{
			best = Math.max(best, hiscoreKillCounts.getOrDefault(ranked, -1));
		}

		if (name.startsWith("the "))
		{
			best = Math.max(best, filedKillCount(name.substring(4)));
		}

		return best;
	}

	private double storedPersonalBest(String countName)
	{
		String name = filedName(countName);
		Double best = configManager.getRSProfileConfiguration(PERSONAL_BEST_GROUP, name, double.class);
		if (best == null && name.startsWith("the "))
		{
			best = configManager.getRSProfileConfiguration(PERSONAL_BEST_GROUP, name.substring(4), double.class);
		}

		return best == null ? -1 : best;
	}

	/**
	 * A count's name the way Chat Commands files it: lower case, and without the
	 * colon its config keys can't hold.
	 */
	private static String filedName(String countName)
	{
		return countName.toLowerCase().replace(":", "");
	}

	private int filedKillCount(String key)
	{
		Integer stored = configManager.getRSProfileConfiguration(KILLCOUNT_GROUP, key, int.class);
		return stored == null ? -1 : stored;
	}

	/**
	 * The bosses to draw right now, oldest first. The list is the plugin's own and
	 * is refilled on the next call.
	 */
	List<TrackedBoss> visibleBosses()
	{
		visible.clear();
		if (bosses.isEmpty() && departed.isEmpty())
		{
			return visible;
		}

		long now = System.currentTimeMillis();
		for (int i = departed.size() - 1; i >= 0; i--)
		{
			TrackedBoss boss = departed.get(i);
			if (now - boss.goneAt >= boss.lingerMs)
			{
				departed.remove(i);
			}
		}

		// A boss counts as in a fight once it has been hurt or the player has
		// turned on it. Which player the boss itself has turned on is not looked at.
		boolean fightOnly = config.showWhen() == ShowWhen.IN_COMBAT;
		Player local = client.getLocalPlayer();
		for (TrackedBoss boss : bosses.values())
		{
			if (visible.size() >= MOST_ORBS)
			{
				break;
			}

			if (fightOnly && !boss.damaged && (local == null || local.getInteracting() != boss.npc))
			{
				continue;
			}

			visible.add(boss);
		}

		for (int i = 0; i < departed.size() && visible.size() < MOST_ORBS; i++)
		{
			visible.add(departed.get(i));
		}

		return visible;
	}

	@Provides
	BossOrbsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BossOrbsConfig.class);
	}
}

package com.bossorbs;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws each boss's orb over the boss itself, for when the orbs are standing in
 * for the game's health bars. It covers the whole game view and has no place of
 * its own to be dragged to, which is why it is a separate overlay from the one
 * that draws the orbs in a fixed spot.
 */
class BossWorldOverlay extends Overlay
{
	private final BossOrbsPlugin plugin;
	private final BossOrbsConfig config;
	private final BossOrbsOverlay orbs;

	@Inject
	private BossWorldOverlay(BossOrbsPlugin plugin, BossOrbsConfig config, BossOrbsOverlay orbs)
	{
		this.plugin = plugin;
		this.config = config;
		this.orbs = orbs;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.replaceBar())
		{
			return null;
		}

		List<TrackedBoss> bosses = plugin.visibleBosses();
		if (!bosses.isEmpty())
		{
			orbs.renderOverHeads(graphics, bosses);
		}

		return null;
	}
}

