package com.bossorbs;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

/**
 * The game's message after a kill, naming what was killed and how many times
 * that now makes.
 */
final class KillCountMessage
{
	/**
	 * The same message RuneLite's Chat Commands reads. The count is wrapped in a
	 * colour tag, and the wording varies with the content: "kill count" for most,
	 * "completion count" for the Gauntlet, plain "count" for the Barrows chest.
	 */
	private static final Pattern MESSAGE = Pattern.compile(
		"Your (?:completion count for |subdued |completed )?(.+?) "
			+ "(?:(?:kill|harvest|lap|completion) )?(?:count )?is: (?:<col=[0-9a-f]+>)?([\\d,]+)");

	final String boss;
	final int count;

	private KillCountMessage(String boss, int count)
	{
		this.boss = boss;
		this.count = count;
	}

	/**
	 * Reads a chat message, returning null if it isn't a kill count.
	 */
	static KillCountMessage parse(String message)
	{
		Matcher matcher = MESSAGE.matcher(message);
		if (!matcher.find())
		{
			return null;
		}

		try
		{
			int count = Integer.parseInt(matcher.group(2).replace(",", ""));
			return new KillCountMessage(Text.removeTags(matcher.group(1)), count);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

