package com.bossorbs;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.image.BufferedImage;

/**
 * Paints the orb itself.
 *
 * <p>Most of an orb never changes: its rim, its shadow, its shine. Those are
 * drawn once for each size and kept as images, so that drawing a frame is a
 * matter of laying down the image and painting only the health on top. That
 * matters because the overlay is redrawn every frame, and shapes and gradients
 * made afresh each time are work for the garbage collector.
 */
final class OrbArt
{
	private static final Color OUTLINE = new Color(0, 0, 0, 235);
	private static final Color INNER_EDGE = new Color(255, 255, 255, 64);
	private static final Color UNLIT = new Color(54, 56, 62);
	private static final Color SHADOW = new Color(0, 0, 0, 34);
	private static final Color HOLLOW = new Color(10, 10, 14);

	private static final int SEGMENTS = 20;

	/** Room around the orb in its images, for the shadow that falls outside it. */
	private static final int MARGIN = 6;

	/** How many sizes of orb, and how many colours of health, are kept ready at once. */
	private static final int KEPT_ORBS = 4;
	private static final int KEPT_LOOKS = 12;

	private static final Stroke SURFACE_LINE = new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER);

	/**
	 * The unchanging parts of one design at one size.
	 */
	private static final class Orb
	{
		OrbDesign design;
		int size;
		int tint;

		/** What goes under the health, and for a glass orb what goes back over it. */
		BufferedImage under;
		BufferedImage over;

		/** Where the hollow of a glass orb starts, and how far across it is. */
		float inset;
		float hollow;

		/** The ticks of a segmented orb, clockwise from the top. */
		Arc2D.Float[] ticks;
		Stroke tickStroke;

		int iconSpace;
	}

	/**
	 * Everything worked out from one colour of health for one orb.
	 */
	private static final class Look
	{
		int rgb;
		Orb orb;
		Paint fill;
		Color surface;
		Color trail;
		Paint trailFill;
		Color trailSurface;
	}

	private final Orb[] orbs = new Orb[KEPT_ORBS];
	private final Look[] looks = new Look[KEPT_LOOKS];
	private int nextOrb;
	private int nextLook;

	/** Reused for every fill, rather than made anew each frame. */
	private final Arc2D.Float segment = new Arc2D.Float(Arc2D.CHORD);
	private final Line2D.Float surface = new Line2D.Float();

	/**
	 * Draws an orb with its top left corner at the given point.
	 *
	 * @param fraction how full of health it is, 0 to 1
	 * @param trail where health stood before recent damage, drawn pale; no more than fraction for none
	 * @param background the colour behind the icon of a segmented orb
	 * @return how much room there is inside the orb for an icon
	 */
	int draw(Graphics2D graphics, OrbDesign design, int x, int y, int size, double fraction, double trail,
		Color colour, Color background)
	{
		Orb orb = orb(design, size, background);
		graphics.drawImage(orb.under, x - MARGIN, y - MARGIN, null);

		Stroke previousStroke = graphics.getStroke();
		Paint previousPaint = graphics.getPaint();
		graphics.translate(x, y);
		if (orb.ticks != null)
		{
			drawTicks(graphics, orb, fraction, trail, colour);
		}
		else
		{
			drawLiquid(graphics, orb, fraction, trail, colour);
		}
		graphics.translate(-x, -y);
		graphics.setStroke(previousStroke);
		graphics.setPaint(previousPaint);

		if (orb.over != null)
		{
			graphics.drawImage(orb.over, x - MARGIN, y - MARGIN, null);
		}

		return orb.iconSpace;
	}

	/**
	 * The liquid in a glass orb, with the pale trail of recent damage above it.
	 */
	private void drawLiquid(Graphics2D graphics, Orb orb, double fraction, double trail, Color colour)
	{
		Look look = look(colour, orb);
		if (trail > fraction)
		{
			fill(graphics, orb, trail, look.trailFill, look.trailSurface);
		}

		fill(graphics, orb, fraction, look.fill, look.surface);
	}

	/**
	 * Fills the hollow of an orb to a level. The filled part of a circle is the
	 * piece cut off by a straight line across it, which can be drawn as it is,
	 * without clipping a rectangle to the circle.
	 */
	private void fill(Graphics2D graphics, Orb orb, double fraction, Paint paint, Color top)
	{
		float span = orb.hollow;
		float level = (float) (span * fraction);
		if (level <= 0.05f)
		{
			return;
		}

		// The angle up from level at which the surface meets the side of the orb:
		// none when half full, a right angle upwards when full.
		float radius = span / 2f;
		double sine = Math.max(-1, Math.min(1, (level - radius) / radius));
		double angle = Math.toDegrees(Math.asin(sine));
		segment.setArc(orb.inset, orb.inset, span, span, 180 - angle, 180 + 2 * angle, Arc2D.CHORD);
		graphics.setPaint(paint);
		graphics.fill(segment);

		if (fraction < 1)
		{
			float height = orb.inset + span - level + 0.5f;
			float half = (float) (radius * Math.cos(Math.toRadians(angle)));
			float centre = orb.inset + radius;
			surface.setLine(centre - half, height, centre + half, height);
			graphics.setColor(top);
			graphics.setStroke(SURFACE_LINE);
			graphics.draw(surface);
		}
	}

	/**
	 * The lit ticks of a segmented orb. The unlit ones are already in its image.
	 */
	private void drawTicks(Graphics2D graphics, Orb orb, double fraction, double trail, Color colour)
	{
		double lit = fraction * SEGMENTS;
		double trailing = trail > fraction ? trail * SEGMENTS : 0;
		int last = Math.min(SEGMENTS, (int) Math.ceil(Math.max(lit, trailing)));
		if (last <= 0)
		{
			return;
		}

		Color pale = trailing > 0 ? look(colour, orb).trail : UNLIT;
		graphics.setStroke(orb.tickStroke);
		for (int i = 0; i < last; i++)
		{
			// The tick at the edge is lit by how much of it is left, so the ring
			// drains evenly instead of a tick at a time.
			Color tick = mix(mix(UNLIT, pale, trailing - i), colour, lit - i);
			if (tick != UNLIT)
			{
				graphics.setColor(tick);
				graphics.draw(orb.ticks[i]);
			}
		}
	}

	private Orb orb(OrbDesign design, int size, Color background)
	{
		// Only a segmented orb shows the background colour.
		int tint = design == OrbDesign.SEGMENTED ? background.getRGB() : 0;
		for (Orb kept : orbs)
		{
			if (kept != null && kept.design == design && kept.size == size && kept.tint == tint)
			{
				return kept;
			}
		}

		Orb made = design == OrbDesign.SEGMENTED ? segmented(size, background) : glass(size);
		made.design = design;
		made.size = size;
		made.tint = tint;
		orbs[nextOrb] = made;
		nextOrb = (nextOrb + 1) % KEPT_ORBS;
		return made;
	}

	private Look look(Color colour, Orb orb)
	{
		int rgb = colour.getRGB();
		for (Look kept : looks)
		{
			if (kept != null && kept.rgb == rgb && kept.orb == orb)
			{
				return kept;
			}
		}

		Look made = new Look();
		made.rgb = rgb;
		made.orb = orb;
		made.fill = gradient(orb, colour);
		made.surface = lighten(colour, 0.55f);
		made.trail = lighten(colour, 0.7f);
		made.trailFill = gradient(orb, made.trail);
		made.trailSurface = lighten(made.trail, 0.55f);
		looks[nextLook] = made;
		nextLook = (nextLook + 1) % KEPT_LOOKS;
		return made;
	}

	/**
	 * Liquid is a little lighter at the top of the orb than at the bottom.
	 */
	private static Paint gradient(Orb orb, Color colour)
	{
		return new GradientPaint(0, orb.inset, lighten(colour, 0.2f), 0, orb.inset + orb.hollow, darken(colour, 0.32f));
	}

	/**
	 * A polished sphere in a metal rim, with a highlight across the top.
	 */
	private static Orb glass(int size)
	{
		Orb orb = new Orb();
		float rim = Math.max(3f, size * 0.08f);
		orb.inset = rim;
		orb.hollow = size - rim * 2;
		orb.iconSpace = Math.round(orb.hollow);

		orb.under = image(size);
		Graphics2D under = canvas(orb.under);
		shadow(under, size);
		Shape outer = circle(size, 0.5f);
		under.setPaint(new GradientPaint(0, 0, new Color(226, 230, 238), 0, size, new Color(58, 62, 72)));
		under.fill(outer);
		stroke(under, outer, 1.3f, OUTLINE);
		Shape hollow = circle(size, rim);
		under.setColor(HOLLOW);
		under.fill(hollow);
		under.dispose();

		// The highlight is what makes it read as glass rather than a flat disc.
		orb.over = image(size);
		Graphics2D over = canvas(orb.over);
		over.clip(hollow);
		over.setPaint(new GradientPaint(0, rim, new Color(255, 255, 255, 120),
			0, rim + orb.hollow * 0.5f, new Color(255, 255, 255, 0)));
		over.fill(new Ellipse2D.Float(rim + orb.hollow * 0.1f, rim + 1, orb.hollow * 0.8f, orb.hollow * 0.52f));
		over.setClip(null);
		stroke(over, hollow, 1.5f, OUTLINE);
		over.dispose();
		return orb;
	}

	/**
	 * A ring cut into ticks around a dark disc. The ticks are all drawn unlit
	 * here, to be lit over the top as health allows.
	 */
	private static Orb segmented(int size, Color background)
	{
		Orb orb = new Orb();
		float width = Math.max(4f, size * 0.11f);
		float inset = 1.5f + width / 2f;
		float step = 360f / SEGMENTS;
		float gap = Math.max(3f, 180f / size);
		float across = size - inset * 2;

		orb.tickStroke = new BasicStroke(width, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER);
		orb.ticks = new Arc2D.Float[SEGMENTS];
		for (int i = 0; i < SEGMENTS; i++)
		{
			orb.ticks[i] = new Arc2D.Float(inset, inset, across, across, 90 - i * step - gap / 2, -(step - gap),
				Arc2D.OPEN);
		}

		orb.under = image(size);
		Graphics2D under = canvas(orb.under);
		shadow(under, size);
		stroke(under, circle(size, inset), width + 2.5f, OUTLINE);
		under.setStroke(orb.tickStroke);
		under.setColor(UNLIT);
		for (Arc2D.Float tick : orb.ticks)
		{
			under.draw(tick);
		}

		float discInset = width + 4;
		Shape disc = circle(size, discInset);
		under.setColor(background);
		under.fill(disc);
		stroke(under, disc, 1.4f, OUTLINE);
		stroke(under, circle(size, discInset + 1.5f), 1f, INNER_EDGE);
		under.dispose();

		orb.iconSpace = Math.round(size - discInset * 2);
		return orb;
	}

	private static BufferedImage image(int size)
	{
		return new BufferedImage(size + MARGIN * 2, size + MARGIN * 2, BufferedImage.TYPE_INT_ARGB);
	}

	/**
	 * Graphics for one of an orb's images, with the orb's top left corner at the origin.
	 */
	private static Graphics2D canvas(BufferedImage image)
	{
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.translate(MARGIN, MARGIN);
		return graphics;
	}

	/**
	 * A soft shadow under the orb, built from a few faint layers since there is no
	 * cheap blur to be had here.
	 */
	private static void shadow(Graphics2D graphics, int size)
	{
		graphics.setColor(SHADOW);
		for (int spread = 3; spread >= 1; spread--)
		{
			graphics.fill(new Ellipse2D.Float(1 - spread, 3 - spread, size + spread * 2 - 2, size + spread * 2 - 2));
		}
	}

	private static Shape circle(int size, float inset)
	{
		return new Ellipse2D.Float(inset, inset, size - inset * 2, size - inset * 2);
	}

	private static void stroke(Graphics2D graphics, Shape shape, float width, Color colour)
	{
		graphics.setStroke(new BasicStroke(width));
		graphics.setColor(colour);
		graphics.draw(shape);
	}

	/**
	 * One colour blended into another: none of it at 0 or below, all of it at 1 or above.
	 */
	private static Color mix(Color from, Color to, double amount)
	{
		if (amount <= 0)
		{
			return from;
		}

		if (amount >= 1)
		{
			return to;
		}

		return new Color(
			(int) Math.round(from.getRed() + (to.getRed() - from.getRed()) * amount),
			(int) Math.round(from.getGreen() + (to.getGreen() - from.getGreen()) * amount),
			(int) Math.round(from.getBlue() + (to.getBlue() - from.getBlue()) * amount));
	}

	private static Color lighten(Color colour, float amount)
	{
		return new Color(
			Math.round(colour.getRed() + (255 - colour.getRed()) * amount),
			Math.round(colour.getGreen() + (255 - colour.getGreen()) * amount),
			Math.round(colour.getBlue() + (255 - colour.getBlue()) * amount));
	}

	private static Color darken(Color colour, float amount)
	{
		return new Color(
			Math.round(colour.getRed() * (1 - amount)),
			Math.round(colour.getGreen() * (1 - amount)),
			Math.round(colour.getBlue() * (1 - amount)));
	}
}

