import java.util.HashMap;
import java.util.Map;

/**
 * How long each boss takes to come back after it dies, for the ones that respawn
 * on a fixed timer. The figures are the ones RuneLite's own Boss Timers uses.
 */
final class RespawnTimes
{
	private static final int TICK_MS = 600;

	private static final Map<String, Integer> BY_NAME = new HashMap<>();

	static
	{
		seconds(90, "General Graardor", "K'ril Tsutsaroth", "Kree'arra", "Commander Zilyana");
		seconds(90, "Dagannoth Prime", "Dagannoth Rex", "Dagannoth Supreme");
		seconds(30, "Corporeal Beast", "Kalphite Queen");
		seconds(12, "Shellbane Gryphon");
		seconds(9, "Crazy archaeologist", "King Black Dragon");

		ticks(11, "Callisto", "Artio");
		ticks(14, "Chaos Elemental", "Chaos Fanatic", "Scorpia", "Calvar'ion");
		ticks(15, "Vet'ion", "Araxxor");
		ticks(10, "Venenatis");
		ticks(9, "Spindel");
		ticks(29, "Scurrius");
		ticks(16, "Sarachnis");
		ticks(50, "Phantom Muspah", "The Hueycoatl");
		ticks(30, "The Leviathan");
		ticks(28, "Amoxliatl");
		ticks(35, "Brutus");

		millis(9000, "Giant Mole");
		millis(29400, "Deranged archaeologist");
		millis(8400, "Cerberus", "Thermonuclear smoke devil", "Kraken");
		millis(25200, "Alchemical Hydra");
		millis(21600, "Zalcano");
	}

	private RespawnTimes()
	{
	}

	/**
	 * The respawn time of the boss with this NPC name in milliseconds, or 0 if it
	 * doesn't have a fixed one.
	 */
	static int of(String npcName)
	{
		return BY_NAME.getOrDefault(BossCatalogue.key(npcName), 0);
	}

	private static void seconds(int seconds, String... names)
	{
		millis(seconds * 1000, names);
	}

	private static void ticks(int ticks, String... names)
	{
		millis(ticks * TICK_MS, names);
	}

	private static void millis(int millis, String... names)
	{
		for (String name : names)
		{
			BY_NAME.put(BossCatalogue.key(name), millis);
		}
	}
}

