package com.bossorbs;

import java.awt.Color;
import java.awt.Font;
import net.runelite.api.NPC;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.hiscore.HiscoreSkill;

/**
 * A boss currently in the scene, with the last health reading taken from it.
 */
final class TrackedBoss
{
	/** How long the orb of a boss that died stays up, so its kill can be marked. */
	static final int LINGER_MS = 3000;

	final NPC npc;
	final HiscoreSkill skill;
	final String name;

	/**
	 * The name its kill count and personal best are kept under, which is the
	 * hiscores entry's. That differs from its own name where several NPCs count
	 * towards one entry, as Dusk and Dawn do.
	 */
	final String countName;

	/**
	 * How full its health is, 0 to 1. Starts full, because the game sends nothing
	 * for an NPC until it is first hit, and is kept between readings, because the
	 * game also stops sending once the fight goes quiet.
	 */
	double fraction = 1;

	/** Current and maximum hitpoints, or -1 when the maximum isn't known. */
	int current = -1;
	int maximum = -1;

	/** Whether it has been seen below full health, which marks a fight as started. */
	boolean damaged;

	/** When it was first seen damaged and when it died, or 0 for not yet. */
	long fightStart;
	long fightEnd;

	/** Whether the current reading is the game's exact figure rather than one taken from the health bar. */
	boolean exact;

	/**
	 * Set when health moved for a reason that isn't a hit or a heal, such as a more
	 * precise reading arriving, so the orb eases to it without making a show of it.
	 */
	boolean quietChange;

	/** When its NPC left the scene dead, or 0 while it is still there. */
	long goneAt;

	/** How long it takes to come back once it has gone, or 0 when that isn't known. */
	int respawnMs;

	/** How long its orb stays up after it has gone. */
	int lingerMs = LINGER_MS;

	// Everything below is the overlay's: where the orb is, and where it is in its animations.

	/**
	 * Where the boss last stood and how tall it is, kept so that an orb drawn over
	 * its head has somewhere to stay once the boss itself has gone.
	 */
	LocalPoint lastPoint;
	int lastHeight;

	/** The point on the canvas just above its head this frame. */
	int headX;
	int headY;

	/** Health as drawn, catching up with {@link #fraction}. Negative until first drawn. */
	double shown = -1;

	/** When its orb was first drawn, which it fades in from. */
	long appearedAt;

	/** The colour as drawn, catching up with the colour of its health band. */
	boolean tinted;
	double red;
	double green;
	double blue;

	/** That colour as an object, and the shade of it its number plate is edged in. */
	Color colour;
	Color edge;

	// What is written on and under the orb, each kept with the figure it was
	// made from so that it is only written again when that figure changes.

	String healthText;
	int healthValue;
	int healthMaximum;
	HealthText healthStyle;

	String timerText;
	long timerSeconds;

	String respawnText;
	long respawnSeconds;

	String killCountText;
	int killCountShown;
	boolean killCountBelow;

	String fittedName;
	int fittedWidth;
	Font fittedFont;

	/** Where health stood before recent damage, drawn pale and then drained. */
	double trail;
	long trailHoldUntil;

	/** How fast the drawn health and its trail are moving, which carries over from one frame to the next. */
	double shownSpeed;
	double trailSpeed;

	/** The reading the animations last reacted to, as a fraction and in hitpoints. */
	double reacted;
	int reactedHealth = -1;

	/** When it was last hit, last healed and last killed, or 0 for never. */
	long hitAt;
	long healAt;
	long killAt;

	/** How much the kill count went up by at the last kill. */
	int killGain = 1;

	/** The last change in hitpoints, as it is written beside the health number. */
	String change;
	long changeAt;
	boolean changeHeal;

	TrackedBoss(NPC npc, HiscoreSkill skill, String name, String countName)
	{
		this.npc = npc;
		this.skill = skill;
		this.name = name;
		this.countName = countName;
	}
}

