package com.bossorbs;

import java.awt.Rectangle;
import java.util.Map;
import java.util.Set;
import okhttp3.HttpUrl;

/**
 * Where an orb is on the canvas and which wiki pages it stands for.
 */
final class WikiTarget
{
	private static final HttpUrl WIKI = HttpUrl.get("https://oldschool.runescape.wiki");

	/**
	 * Bosses whose strategy guide is filed under something other than their own
	 * name, by the name their kills are counted under.
	 */
	private static final Map<String, String> GUIDES = Map.of(
		BossCatalogue.key("The Royal Titans"), "Royal Titans",
		BossCatalogue.key("The Corrupted Gauntlet"), "The Gauntlet",
		BossCatalogue.key("Dagannoth Prime"), "Dagannoth Kings",
		BossCatalogue.key("Dagannoth Rex"), "Dagannoth Kings",
		BossCatalogue.key("Dagannoth Supreme"), "Dagannoth Kings",
		BossCatalogue.key("TzTok-Jad"), "TzHaar Fight Cave",
		BossCatalogue.key("TzKal-Zuk"), "Inferno");

	/** Bosses the wiki has no strategy guide for. */
	private static final Set<String> NO_GUIDE = Set.of(BossCatalogue.key("Obor"), BossCatalogue.key("Bryophyta"));

	final Rectangle bounds;
	final String name;

	/** The name the boss's kills are counted under, which is what a shared guide goes by. */
	private final String countName;

	private final int npcId;

	WikiTarget(Rectangle bounds, String name, String countName, int npcId)
	{
		this.bounds = bounds;
		this.name = name;
		this.countName = countName;
		this.npcId = npcId;
	}

	/**
	 * The wiki's own lookup by NPC id, which lands on the right page for a boss
	 * with several forms.
	 */
	String url()
	{
		return WIKI.newBuilder()
			.addPathSegments("w/Special:Lookup")
			.addQueryParameter("type", "npc")
			.addQueryParameter("id", String.valueOf(npcId))
			.addQueryParameter("name", name)
			.addQueryParameter("utm_source", "runelite")
			.build().toString();
	}

	/**
	 * The boss's strategy guide, or null if the wiki doesn't have one. It goes
	 * through the wiki's search, which jumps straight to a page of that exact
	 * title and offers the nearest ones when there isn't one.
	 */
	String strategiesUrl()
	{
		String page = guidePage(name, countName);
		if (page == null)
		{
			return null;
		}

		return WIKI.newBuilder()
			.addPathSegments("w/Special:Search")
			.addQueryParameter("search", page + "/Strategies")
			.addQueryParameter("utm_source", "runelite")
			.build().toString();
	}

	/**
	 * The page a boss's strategy guide hangs off, or null if it has none.
	 */
	static String guidePage(String name, String countName)
	{
		String counted = BossCatalogue.key(countName);
		if (NO_GUIDE.contains(counted))
		{
			return null;
		}

		String filed = GUIDES.get(counted);
		if (filed != null)
		{
			return filed;
		}

		// A boss counted under its own name uses that name as the game writes it,
		// "The Nightmare" rather than the hiscores' "Nightmare". One of several
		// NPCs counted together, like Dusk and Dawn, shares the group's guide.
		return withoutThe(BossCatalogue.key(name)).equals(withoutThe(counted)) ? name : countName;
	}

	private static String withoutThe(String key)
	{
		return key.startsWith("the") ? key.substring(3) : key;
	}
}

package com.bossorbs;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import net.runelite.client.hiscore.HiscoreSkill;
import org.junit.Test;

public class BossCatalogueTest
{
	private final BossCatalogue catalogue = new BossCatalogue();

	@Test
	public void bossesAreFoundByTheirOwnNames()
	{
		for (String name : new String[]{"Zulrah", "Vorkath", "General Graardor", "Kree'arra", "TzTok-Jad"})
		{
			assertNotNull(name, catalogue.match(name));
		}
	}

	@Test
	public void punctuationAndCaseDoNotMatter()
	{
		assertSame(catalogue.match("Kree'arra"), catalogue.match("KREE ARRA"));
		assertSame(catalogue.match("TzTok-Jad"), catalogue.match("tztok jad"));
	}

	@Test
	public void colourTagsAreIgnored()
	{
		assertSame(catalogue.match("Vorkath"), catalogue.match("<col=ffff00>Vorkath</col>"));
	}

	@Test
	public void aLeadingTheIsOptionalEitherWay()
	{
		assertNotNull(catalogue.match("The Nightmare"));
		assertSame(catalogue.match("Nightmare"), catalogue.match("The Nightmare"));
		assertNotNull(catalogue.match("Hueycoatl"));
		assertSame(catalogue.match("The Hueycoatl"), catalogue.match("Hueycoatl"));
	}

	@Test
	public void npcsNamedDifferentlyCountTowardsTheirHiscoresEntry()
	{
		assertEntry("Grotesque Guardians", "Dusk");
		assertEntry("Grotesque Guardians", "Dawn");
		assertEntry("The Gauntlet", "Crystalline Hunllef");
		assertEntry("The Corrupted Gauntlet", "Corrupted Hunllef");
		assertEntry("The Royal Titans", "Branda the Fire Queen");
	}

	@Test
	public void raidBossesAreLeftOut()
	{
		for (String name : new String[]{"Great Olm", "Tekton", "Verzik Vitur", "Sotetseg", "Kephri", "Akkha"})
		{
			assertNull(name, catalogue.match(name));
		}
	}

	@Test
	public void bossesOnTheWayToAChestAreLeftOut()
	{
		for (String name : new String[]{"Dharok the Wretched", "Ahrim the Blighted", "Verac the Defiled",
			"Blood Moon", "Blue Moon", "Eclipse Moon"})
		{
			assertNull(name, catalogue.match(name));
		}
	}

	@Test
	public void ordinaryNpcsAreNotBosses()
	{
		assertNull(catalogue.match("Goblin"));
		assertNull(catalogue.match("Banker"));
		assertNull(catalogue.match(""));
		assertNull(catalogue.match(null));
	}

	@Test
	public void hiscoreLooksUpEntriesButNotTheNpcsThatCountTowardsThem()
	{
		assertNotNull(catalogue.hiscore("Grotesque Guardians"));
		assertNull(catalogue.hiscore("Dusk"));
	}

	private void assertEntry(String entry, String npcName)
	{
		HiscoreSkill skill = catalogue.match(npcName);
		assertNotNull(npcName, skill);
		assertEquals(npcName, entry, skill.getName());
	}
}

