package com.bossorbs;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The health bar is a coarse fraction, and hitpoints are worked back from it.
 */
public class HealthEstimateTest
{
	@Test
	public void aFullBarIsFullHealth()
	{
		assertEquals(255, BossOrbsPlugin.estimate(30, 30, 255));
		assertEquals(750, BossOrbsPlugin.estimate(30, 30, 750));
	}

	@Test
	public void anEmptyBarIsNoHealth()
	{
		assertEquals(0, BossOrbsPlugin.estimate(0, 30, 255));
	}

	@Test
	public void aBarTooCoarseToReadIsTakenAsFull()
	{
		assertEquals(255, BossOrbsPlugin.estimate(1, 1, 255));
	}

	@Test
	public void halfABarIsAboutHalfTheHealth()
	{
		int estimate = BossOrbsPlugin.estimate(15, 30, 750);
		assertTrue("was " + estimate, estimate > 350 && estimate < 400);
	}

	@Test
	public void theEstimateNeverRisesAsTheBarFalls()
	{
		int previous = Integer.MAX_VALUE;
		for (int ratio = 30; ratio >= 0; ratio--)
		{
			int estimate = BossOrbsPlugin.estimate(ratio, 30, 500);
			assertTrue("at " + ratio, estimate <= previous);
			assertTrue("at " + ratio, estimate >= 0 && estimate <= 500);
			previous = estimate;
		}
	}

	@Test
	public void theLastSliverOfTheBarIsNotZero()
	{
		assertTrue(BossOrbsPlugin.estimate(1, 30, 500) > 0);
	}
}

