	public void theChestsKeepTheirWholeName()
	{
		assertCount("Barrows chest", 12, "Your Barrows chest count is: <col=ff0000>12</col>.");
		assertCount("Lunar Chest", 3, "Your Lunar Chest count is: <col=ff0000>3</col>.");
