	{
		assertCount("Gauntlet", 40, "Your Gauntlet completion count is: <col=ff0000>40</col>.");
		assertCount("Corrupted Gauntlet", 5, "Your Corrupted Gauntlet completion count is: <col=ff0000>5</col>.");
		assertCount("Wintertodt", 120, "Your subdued Wintertodt count is: <col=ff0000>120</col>.");
	}

	@Test
	public void countsInTheThousands()
	{
		assertCount("Vorkath", 1234, "Your Vorkath kill count is: <col=ff0000>1,234</col>.");
	}

